      "path": "scripts/package-app.sh",
      "content": "#!/usr/bin/env bash\nset -euo pipefail\n\nROOT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")/..\" && pwd)\"\nAPP_DIR=\"$HOME/Applications\"\nAPP_PATH=\"$APP_DIR/Codex Switch.app\"\nBUILD_DIR=\"$(mktemp -d)\"\nBUILD_APP=\"$BUILD_DIR/Codex Switch.app\"\nXCODE_DEVELOPER_DIR=\"${DEVELOPER_DIR:-}\"\n\n# A full Xcode (not just Command Line Tools) is required to build SwiftUI code,\n# because CLT lacks the SwiftUI macro plugins. Search common install locations.\nif [[ -z \"$XCODE_DEVELOPER_DIR\" ]]; then\n  for candidate in \\\n    \"$HOME/Desktop/Xcode-beta.app\" \\\n    \"$HOME/Downloads/Xcode-beta.app\" \\\n    \"/Applications/Xcode.app\" \\\n    \"/Applications/Xcode-beta.app\" \\\n    \"$HOME/Applications/Xcode.app\"; do\n    if [[ -d \"$candidate/Contents/Developer\" ]]; then\n      XCODE_DEVELOPER_DIR=\"$candidate/Contents/Developer\"\n      break\n    fi\n  done\nfi\n\n# Fall back to the active developer dir if it is a full Xcode.\nif [[ -z \"$XCODE_DEVELOPER_DIR\" ]]; then\n  active=\"$(xcode-select -p 2>/dev/null || true)\"\n  if [[ \"$active\" == *\"/Xcode\"*\".app/\"* ]]; then\n    XCODE_DEVELOPER_DIR=\"$active\"\n  fi\nfi\n\nif [[ -n \"$XCODE_DEVELOPER_DIR\" ]]; then\n  SWIFTC=\"$XCODE_DEVELOPER_DIR/Toolchains/XcodeDefault.xctoolchain/usr/bin/swiftc\"\n  SDK_PATH=\"$XCODE_DEVELOPER_DIR/Platforms/MacOSX.platform/Developer/SDKs/MacOSX.sdk\"\nelse\n  SWIFTC=\"$(command -v swiftc || true)\"\n  SDK_PATH=\"$(xcrun --sdk macosx --show-sdk-path)\"\nfi\n\nif [[ -z \"$SWIFTC\" || ! -x \"$SWIFTC\" ]]; then\n  echo \"swiftc is required. This packager runs on macOS.\" >&2\n  exit 1\nfi\n\ntrap 'rm -rf \"$BUILD_DIR\"' EXIT\nmkdir -p \"$BUILD_APP/Contents/MacOS\" \"$BUILD_APP/Contents/Resources\" \"$APP_DIR\"\ncp \"$ROOT_DIR/app/Info.plist\" \"$BUILD_APP/Contents/Info.plist\"\ncp \"$ROOT_DIR/assets/app-icon.icns\" \"$BUILD_APP/Contents/Resources/app-icon.icns\"\ncp \"$ROOT_DIR/src/codex_switch/cli.py\" \"$BUILD_APP/Contents/Resources/codex-switch\"\nchmod 755 \"$BUILD_APP/Contents/Resources/codex-switch\"\n# Build a universal binary (arm64 + x86_64) so the app runs on both Apple\n# Silicon and Intel Macs. Compiling only for the build host's arch produces a\n# single-arch app that fails to launch on the other architecture\n# (\"this Mac does not support this application\").\nARCH_BINARIES=()\nfor arch in arm64 x86_64; do\n  arch_out=\"$BUILD_DIR/Codex Switch-$arch\"\n  CLANG_MODULE_CACHE_PATH=\"$BUILD_DIR/clang-cache-$arch\" \\\n  SWIFT_MODULECACHE_PATH=\"$BUILD_DIR/swift-cache-$arch\" \\\n  \"$SWIFTC\" \\\n    -parse-as-library \\\n    -O \\\n    -target \"$arch-apple-macos13.0\" \\\n    -sdk \"$SDK_PATH\" \\\n    -framework SwiftUI \\\n    -framework AppKit \\\n    \"$ROOT_DIR/app/CodexSwitchApp.swift\" \\\n    -o \"$arch_out\"\n  ARCH_BINARIES+=(\"$arch_out\")\ndone\nlipo -create \"${ARCH_BINARIES[@]}\" -output \"$BUILD_APP/Contents/MacOS/Codex Switch\"\n\n# Sign with a Developer ID Application identity when available. Timestamping\n# contacts Apple's timestamp service, so local builds stay offline unless it is\n# explicitly enabled for a notarized release.\n# Fall back to ad-hoc signing for local dev builds.\nSIGN_ID=\"${CODEX_SWITCH_SIGN_ID:-$(security find-identity -v -p codesigning 2>/dev/null | awk -F'\"' '/Developer ID Application/{print $2; exit}')}\"\nif [[ -n \"$SIGN_ID\" ]]; then\n  echo \"Signing with: $SIGN_ID\" >&2\n  SIGN_ARGS=(--force --deep --options runtime --sign \"$SIGN_ID\")\n  if [[ \"${CODEX_SWITCH_TIMESTAMP_SIGN:-0}\" == \"1\" ]]; then\n    SIGN_ARGS+=(--timestamp)\n  fi\n  codesign \"${SIGN_ARGS[@]}\" \"$BUILD_APP\"\nelse\n  echo \"No Developer ID identity found; ad-hoc signing (not notarizable).\" >&2\n  codesign --force --deep --sign - \"$BUILD_APP\" >/dev/null\nfi\ncodesign --verify --deep --strict \"$BUILD_APP\"\nrm -rf \"$APP_PATH\"\nditto \"$BUILD_APP\" \"$APP_PATH\"\necho \"$APP_PATH\"\n"
