      "path": "src/codex_switch/cli.py",
      "content": "#!/usr/bin/env python3\n\"\"\"Switch Codex auth/config between ChatGPT login and local Responses API.\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport copy\nimport getpass\nimport http.server\nimport json\nimport mmap\nimport os\nimport re\nimport shlex\nimport shutil\nimport sqlite3\nimport stat\nimport subprocess\nimport sys\nimport tempfile\nimport time\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nimport uuid\nfrom datetime import datetime\nfrom pathlib import Path\nfrom xml.sax.saxutils import escape as xml_escape\n\n\nDEFAULT_BASE_URL = \"https://jp.icodeeasy.cc\"\nDEFAULT_MODEL = \"gpt-5.5\"\nDEFAULT_OFFICIAL_MODEL = \"gpt-6.1-sol\"\nCUSTOM_MODEL_SLUG_PREFIX = \"codex-switch/\"\nDEFAULT_CUSTOM_MODEL = f\"{CUSTOM_MODEL_SLUG_PREFIX}gpt-5.5\"\nDEFAULT_UPSTREAM_MODEL = \"gpt-5.5\"\nDEFAULT_ADAPTER_HOST = \"127.0.0.1\"\nDEFAULT_ADAPTER_PORT = 17638\nADAPTER_LAUNCH_AGENT_LABEL = \"com.kuangre.codex-switch.adapter\"\nPROXY_LAUNCH_AGENT_LABEL = \"com.kuangre.codex-switch.proxy\"\nDEFAULT_ADAPTER_BASE_URL = f\"http://{DEFAULT_ADAPTER_HOST}:{DEFAULT_ADAPTER_PORT}/v1\"\nCLAUDE_DEFAULT_BASE_URL = \"http://127.0.0.1:15721\"\nCLAUDE_DEFAULT_MODEL = \"claude-sonnet-4-6\"\nCLAUDE_DEFAULT_OFFICIAL_MODEL = \"claude-sonnet-4-6\"\nRESTART_SETTLE_SECONDS = 3.0\nUPSTREAM_USER_AGENT = \"CodexSwitch/1.0\"\nCONFIG_KEYS = (\"local_base_url\", \"local_model\", \"local_upstream_model\", \"official_model\")\nCUSTOM_PROVIDER_ID = \"custom\"\nMODEL_CATALOG_NAME = \"codex-switch-model-catalog.json\"\nMESSAGE_ID_REPAIR_VERSION = 1\nMESSAGE_ID_REPAIR_STATE_KEY = \"message_id_repair_version\"\nDEFAULT_NO_PROXY = \"localhost,127.0.0.1,::1\"\nPROXY_ENV_KEYS = (\"HTTP_PROXY\", \"HTTPS_PROXY\", \"http_proxy\", \"https_proxy\")\nNO_PROXY_ENV_KEYS = (\"NO_PROXY\", \"no_proxy\")\nREASONING_EFFORTS = (\"low\", \"medium\", \"high\", \"xhigh\")\nDEFAULT_REASONING_EFFORT = \"xhigh\"\n\n\nclass SwitchError(RuntimeError):\n    pass\n\n\ndef _looks_translocated(path: Path) -> bool:\n    # Under macOS App Translocation (running a quarantined app straight from a\n    # DMG/Downloads) or a sandbox, $HOME is redirected to a throwaway temp\n    # directory. A real home is never under /var/folders or an AppTranslocation\n    # path. (\"/var/folders/\" also matches the /private/var/folders/ variant.)\n    marker = str(path)\n    return \"/AppTranslocation/\" in marker or \"/var/folders/\" in marker\n\n\ndef _real_user_home() -> Path:\n    \"\"\"The account's real home from the user database, immune to $HOME\n    redirection under App Translocation / sandboxing.\"\"\"\n    try:\n        import pwd\n\n        return Path(pwd.getpwuid(os.getuid()).pw_dir)\n    except Exception:\n        return Path.home()\n\n\ndef _resolved_home() -> Path:\n    # Only override the default home when $HOME looks translocated; an explicit\n    # CODEX_HOME/CLAUDE_CONFIG_DIR (used by tests and power users) always wins\n    # and is handled by the callers before this is consulted.\n    home = Path.home()\n    if _looks_translocated(home):\n        real = _real_user_home()\n        if not _looks_translocated(real):\n            return real\n    return home\n\n\ndef codex_home() -> Path:\n    env = os.environ.get(\"CODEX_HOME\")\n    if env:\n        return Path(env).expanduser()\n    return (_resolved_home() / \".codex\").expanduser()\n\n\ndef claude_home() -> Path:\n    env = os.environ.get(\"CLAUDE_CONFIG_DIR\")\n    if env:\n        return Path(env).expanduser()\n    return (_resolved_home() / \".claude\").expanduser()\n\n\ndef redacted_key(value: str | None) -> str:\n    if not value:\n        return \"(none)\"\n    if len(value) <= 8:\n        return \"***\"\n    return f\"{value[:3]}...{value[-4:]}\"\n\n\ndef load_auth(auth_path: Path) -> dict[str, object]:\n    if not auth_path.exists():\n        return {}\n    try:\n        data = json.loads(auth_path.read_text(encoding=\"utf-8\"))\n    except json.JSONDecodeError as exc:\n        raise SwitchError(f\"Invalid JSON in {auth_path}: {exc}\") from exc\n    if not isinstance(data, dict):\n        raise SwitchError(f\"Expected {auth_path} to contain a JSON object\")\n    return data\n\n\ndef load_json_object(path: Path) -> dict[str, object]:\n    if not path.exists():\n        return {}\n    try:\n        data = json.loads(path.read_text(encoding=\"utf-8\"))\n    except json.JSONDecodeError as exc:\n        raise SwitchError(f\"Invalid JSON in {path}: {exc}\") from exc\n    if not isinstance(data, dict):\n        raise SwitchError(f\"Expected {path} to contain a JSON object\")\n    return data\n\n\ndef state_path(home: Path) -> Path:\n    return home / \"codex-switch-state.json\"\n\n\ndef claude_state_path(home: Path) -> Path:\n    return home / \"claude-switch-state.json\"\n\n\ndef load_state(home: Path) -> dict[str, object]:\n    path = state_path(home)\n    if not path.exists():\n        return {}\n    try:\n        data = json.loads(path.read_text(encoding=\"utf-8\"))\n    except json.JSONDecodeError as exc:\n        raise SwitchError(f\"Invalid JSON in {path}: {exc}\") from exc\n    if not isinstance(data, dict):\n        raise SwitchError(f\"Expected {path} to contain a JSON object\")\n    return data\n\n\ndef save_state(home: Path, state: dict[str, object]) -> None:\n    atomic_write(state_path(home), json.dumps(state, indent=2, sort_keys=True) + \"\\n\", 0o600)\n\n\ndef load_claude_state(home: Path) -> dict[str, object]:\n    path = claude_state_path(home)\n    if not path.exists():\n        return {}\n    data = load_json_object(path)\n    return data\n\n\ndef save_claude_state(home: Path, state: dict[str, object]) -> None:\n    atomic_write(claude_state_path(home), json.dumps(state, indent=2, sort_keys=True) + \"\\n\", 0o600)\n\n\ndef effective_setting(state: dict[str, object], key: str, fallback: str) -> str:\n    value = state.get(key)\n    return value.strip() if isinstance(value, str) and value.strip() else fallback\n\n\ndef remember_current_auth(home: Path, auth: dict[str, object], state: dict[str, object]) -> None:\n    api_key = auth.get(\"OPENAI_API_KEY\")\n    if isinstance(api_key, str) and api_key.strip():\n        state[\"local_api_key\"] = api_key.strip()\n    state.pop(\"official_auth\", None)\n\n\nSTASHED_LOGIN_KEY = \"stashed_chatgpt_login\"\n\n\ndef stash_login_tokens(auth: dict[str, object], state: dict[str, object]) -> None:\n    \"\"\"Move the ChatGPT OAuth login from auth.json into the state file.\n\n    Skip-login must remove `tokens` from auth.json (Codex would otherwise keep\n    preferring the ChatGPT login), but deleting them forced a fresh OAuth login\n    on the next switch to the official provider. Stash them instead; the state\n    file has the same 0600 permissions as auth.json. When auth.json has no\n    tokens (already skipped before), any earlier stash is kept as-is.\n    \"\"\"\n    tokens = auth.get(\"tokens\")\n    if isinstance(tokens, dict) and tokens:\n        stash: dict[str, object] = {\"tokens\": tokens}\n        last_refresh = auth.get(\"last_refresh\")\n        if last_refresh:\n            stash[\"last_refresh\"] = last_refresh\n        state[STASHED_LOGIN_KEY] = stash\n\n\ndef restore_login_tokens(auth: dict[str, object], state: dict[str, object]) -> bool:\n    \"\"\"Put a stashed ChatGPT login back into auth.json for chatgpt-mode writes.\n\n    A live login in auth.json wins over the stash: the user re-logged in after\n    the stash was taken, so the stash is stale and gets dropped either way.\n    \"\"\"\n    if isinstance(auth.get(\"tokens\"), dict) and auth.get(\"tokens\"):\n        state.pop(STASHED_LOGIN_KEY, None)\n        return False\n    stash = state.pop(STASHED_LOGIN_KEY, None)\n    if not isinstance(stash, dict):\n        return False\n    tokens = stash.get(\"tokens\")\n    if not isinstance(tokens, dict) or not tokens:\n        return False\n    auth[\"tokens\"] = tokens\n    last_refresh = stash.get(\"last_refresh\")\n    if last_refresh and not auth.get(\"last_refresh\"):\n        auth[\"last_refresh\"] = last_refresh\n    return True\n\n\ndef backup_file(path: Path, backup_dir: Path) -> Path | None:\n    if not path.exists():\n        return None\n    backup_dir.mkdir(parents=True, exist_ok=True)\n    timestamp = datetime.now().strftime(\"%Y%m%d-%H%M%S\")\n    target = backup_dir / f\"{path.name}.{timestamp}.bak\"\n    counter = 1\n    while target.exists():\n        target = backup_dir / f\"{path.name}.{timestamp}.{counter}.bak\"\n        counter += 1\n    shutil.copy2(path, target)\n    return target\n\n\ndef atomic_write(path: Path, content: str, mode: int = 0o600) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    fd, tmp_name = tempfile.mkstemp(prefix=f\".{path.name}.\", dir=str(path.parent), text=True)\n    tmp_path = Path(tmp_name)\n    try:\n        with os.fdopen(fd, \"w\", encoding=\"utf-8\") as handle:\n            handle.write(content)\n        os.chmod(tmp_path, mode)\n        os.replace(tmp_path, path)\n    finally:\n        if tmp_path.exists():\n            tmp_path.unlink()\n\n\ndef write_auth(auth_path: Path, auth: dict[str, object]) -> None:\n    atomic_write(auth_path, json.dumps(auth, indent=2, sort_keys=True) + \"\\n\", 0o600)\n\n\ndef split_toml_sections(content: str) -> list[tuple[str, list[str]]]:\n    sections: list[tuple[str, list[str]]] = []\n    current = \"\"\n    lines: list[str] = []\n    for line in content.splitlines(keepends=True):\n        stripped = line.strip()\n        if stripped.startswith(\"[\") and stripped.endswith(\"]\"):\n            sections.append((current, lines))\n            current = stripped\n            lines = [line]\n        else:\n            lines.append(line)\n    sections.append((current, lines))\n    return sections\n\n\ndef set_key(lines: list[str], key: str, value: str) -> list[str]:\n    pattern = re.compile(rf\"^(\\s*){re.escape(key)}\\s*=\")\n    rendered = f'{key} = \"{value}\"\\n'\n    for index, line in enumerate(lines):\n        if pattern.match(line):\n            lines[index] = rendered\n            return lines\n    insert_at = len(lines)\n    while insert_at > 0 and lines[insert_at - 1].strip() == \"\":\n        insert_at -= 1\n    lines.insert(insert_at, rendered)\n    return lines\n\n\ndef set_raw_key(lines: list[str], key: str, rendered_value: str) -> list[str]:\n    pattern = re.compile(rf\"^(\\s*){re.escape(key)}\\s*=\")\n    rendered = f\"{key} = {rendered_value}\\n\"\n    for index, line in enumerate(lines):\n        if pattern.match(line):\n            lines[index] = rendered\n            return lines\n    insert_at = len(lines)\n    while insert_at > 0 and lines[insert_at - 1].strip() == \"\":\n        insert_at -= 1\n    lines.insert(insert_at, rendered)\n    return lines\n\n\ndef quoted_array(values: list[str]) -> str:\n    return \"[\" + \", \".join(json.dumps(value) for value in values) + \"]\"\n\n\ndef set_bool_key(lines: list[str], key: str, value: bool) -> list[str]:\n    pattern = re.compile(rf\"^(\\s*){re.escape(key)}\\s*=\")\n    rendered = f\"{key} = {'true' if value else 'false'}\\n\"\n    for index, line in enumerate(lines):\n        if pattern.match(line):\n            lines[index] = rendered\n            return lines\n    insert_at = len(lines)\n    while insert_at > 0 and lines[insert_at - 1].strip() == \"\":\n        insert_at -= 1\n    lines.insert(insert_at, rendered)\n    return lines\n\n\ndef remove_key(lines: list[str], key: str) -> list[str]:\n    pattern = re.compile(rf\"^\\s*{re.escape(key)}\\s*=\")\n    return [line for line in lines if not pattern.match(line)]\n\n\ndef ensure_custom_provider(sections: list[tuple[str, list[str]]], base_url: str, api_key: str, models: list[str]) -> list[tuple[str, list[str]]]:\n    updated: list[tuple[str, list[str]]] = []\n    found = False\n    for section, lines in sections:\n        if section == f\"[model_providers.{CUSTOM_PROVIDER_ID}]\":\n            found = True\n            lines = set_key(lines, \"base_url\", base_url)\n            lines = set_key(lines, \"name\", CUSTOM_PROVIDER_ID)\n            lines = set_bool_key(lines, \"requires_openai_auth\", False)\n            lines = set_key(lines, \"wire_api\", \"responses\")\n            lines = set_key(lines, \"experimental_bearer_token\", api_key)\n            lines = set_raw_key(lines, \"models\", quoted_array(models))\n            # Strip stale env-var auth keys from older configs. When env_key is\n            # present Codex demands that environment variable and ignores\n            # experimental_bearer_token, which breaks the desktop app (GUI apps\n            # don't inherit the shell's CODEX_CUSTOM_API_KEY).\n            lines = remove_key(lines, \"env_key\")\n            lines = remove_key(lines, \"env_key_instructions\")\n        updated.append((section, lines))\n    if not found:\n        lines = [\n            \"\\n\" if updated and updated[-1][1] and updated[-1][1][-1].strip() else \"\",\n            f\"[model_providers.{CUSTOM_PROVIDER_ID}]\\n\",\n            f'base_url = \"{base_url}\"\\n',\n            f'name = \"{CUSTOM_PROVIDER_ID}\"\\n',\n            \"requires_openai_auth = false\\n\",\n            'wire_api = \"responses\"\\n',\n            f'experimental_bearer_token = \"{api_key}\"\\n',\n            f\"models = {quoted_array(models)}\\n\",\n        ]\n        updated.append((f\"[model_providers.{CUSTOM_PROVIDER_ID}]\", lines))\n    return updated\n\n\ndef ensure_profile(\n    sections: list[tuple[str, list[str]]], profile: str, settings: dict[str, str]\n) -> list[tuple[str, list[str]]]:\n    # Profiles let the Codex CLI (`codex --profile <name>`) select a provider +\n    # model without touching the top-level config the desktop app reads.\n    header = f\"[profiles.{profile}]\"\n    updated: list[tuple[str, list[str]]] = []\n    found = False\n    for section, lines in sections:\n        if section == header:\n            found = True\n            for key, value in settings.items():\n                lines = set_key(lines, key, value)\n        updated.append((section, lines))\n    if not found:\n        lines = [\"\\n\" if updated and updated[-1][1] and updated[-1][1][-1].strip() else \"\", f\"{header}\\n\"]\n        lines.extend(f'{key} = \"{value}\"\\n' for key, value in settings.items())\n        updated.append((header, lines))\n    return updated\n\n\ndef normalize_proxy_url(value: str) -> str:\n    raw = value.strip()\n    if not raw:\n        raise SwitchError(\"proxy URL cannot be empty\")\n    if \"://\" not in raw:\n        raw = \"http://\" + raw\n    parsed = urllib.parse.urlparse(raw)\n    if parsed.scheme != \"http\":\n        raise SwitchError(\"proxy URL must use the HTTP proxy protocol, for example http://127.0.0.1:7897\")\n    if not parsed.hostname or parsed.port is None:\n        raise SwitchError(\"proxy URL must include host and port, for example http://127.0.0.1:7897\")\n    if parsed.username or parsed.password:\n        raise SwitchError(\"proxy URL must not include usernames, passwords, or tokens\")\n    if parsed.path not in {\"\", \"/\"} or parsed.params or parsed.query or parsed.fragment:\n        raise SwitchError(\"proxy URL must only contain scheme, host and port\")\n    return f\"http://{parsed.hostname}:{parsed.port}\"\n\n\ndef proxy_launch_agent_path() -> Path:\n    return Path.home() / \"Library\" / \"LaunchAgents\" / f\"{PROXY_LAUNCH_AGENT_LABEL}.plist\"\n\n\ndef enable_launch_agent(label: str) -> None:\n    # Switching an item off under System Settings > General > Login Items &\n    # Extensions > Allow in the Background records the service as \"disabled\" in\n    # launchd's per-user override database. From then on every `launchctl\n    # bootstrap` of it fails with the opaque \"5: Input/output error\" (launchd's\n    # own log says \"119: Service is disabled\"). Clearing the override is\n    # idempotent and needs no root for the user's own gui domain.\n    subprocess.run([\"launchctl\", \"enable\", f\"{launchctl_gui_target()}/{label}\"], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n\n\ndef clash_verge_config_candidates() -> list[Path]:\n    base = Path.home() / \"Library\" / \"Application Support\" / \"io.github.clash-verge-rev.clash-verge-rev\"\n    return [base / \"clash-verge.yaml\", base / \"clash-verge-check.yaml\", base / \"config.yaml\"]\n\n\ndef detect_clash_verge_proxy_url() -> str | None:\n    ports: dict[str, int] = {}\n    for path in clash_verge_config_candidates():\n        if not path.exists():\n            continue\n        try:\n            for line in path.read_text(encoding=\"utf-8\", errors=\"replace\").splitlines():\n                match = re.match(r\"^\\s*(mixed-port|port)\\s*:\\s*([0-9]+)\\s*(?:#.*)?$\", line)\n                if match:\n                    ports.setdefault(match.group(1), int(match.group(2)))\n        except OSError:\n            continue\n    port = ports.get(\"mixed-port\") or ports.get(\"port\")\n    if port:\n        return f\"http://127.0.0.1:{port}\"\n    return None\n\n\ndef find_toml_section(sections: list[tuple[str, list[str]]], header: str) -> tuple[int, list[str]] | None:\n    for index, (section, lines) in enumerate(sections):\n        if section == header:\n            return index, lines\n    return None\n\n\ndef rewrite_config_for_proxy(content: str, proxy_url: str, no_proxy: str) -> str:\n    sections = split_toml_sections(content)\n    header = \"[shell_environment_policy.set]\"\n    found = find_toml_section(sections, header)\n    if found is None:\n        lines = [\"\\n\" if sections and sections[-1][1] and sections[-1][1][-1].strip() else \"\", f\"{header}\\n\"]\n        sections.append((header, lines))\n    else:\n        _, lines = found\n    for key in PROXY_ENV_KEYS:\n        lines = set_key(lines, key, proxy_url)\n    for key in NO_PROXY_ENV_KEYS:\n        lines = set_key(lines, key, no_proxy)\n    return \"\".join(line for _, section_lines in sections for line in section_lines)\n\n\ndef rewrite_config_without_proxy(content: str) -> str:\n    sections = split_toml_sections(content)\n    header = \"[shell_environment_policy.set]\"\n    found = find_toml_section(sections, header)\n    if found is None:\n        return content\n    index, lines = found\n    for key in (*PROXY_ENV_KEYS, *NO_PROXY_ENV_KEYS):\n        lines = remove_key(lines, key)\n    sections[index] = (header, lines)\n    return \"\".join(line for _, section_lines in sections for line in section_lines)\n\n\ndef toml_section_value(content: str, header: str, key: str) -> str | None:\n    for section, lines in split_toml_sections(content):\n        if section != header:\n            continue\n        for line in lines:\n            match = re.match(rf\"^\\s*{re.escape(key)}\\s*=\\s*\\\"([^\\\"]*)\\\"\", line)\n            if match:\n                return match.group(1)\n    return None\n\n\ndef shell_proxy_config_values(content: str) -> dict[str, str]:\n    values: dict[str, str] = {}\n    for key in (*PROXY_ENV_KEYS, *NO_PROXY_ENV_KEYS):\n        value = toml_section_value(content, \"[shell_environment_policy.set]\", key)\n        if value is not None:\n            values[key] = value\n    return values\n\n\ndef launchctl_getenv(key: str) -> str | None:\n    if sys.platform != \"darwin\":\n        return None\n    result = subprocess.run([\"launchctl\", \"getenv\", key], check=False, capture_output=True, text=True)\n    if result.returncode != 0:\n        return None\n    value = result.stdout.strip()\n    return value or None\n\n\ndef set_launchd_proxy(proxy_url: str, no_proxy: str) -> None:\n    if sys.platform != \"darwin\":\n        print(\"launchd_warn: launchctl setenv is only available on macOS; skipped.\")\n        return\n    for key in PROXY_ENV_KEYS:\n        subprocess.run([\"launchctl\", \"setenv\", key, proxy_url], check=True)\n    for key in NO_PROXY_ENV_KEYS:\n        subprocess.run([\"launchctl\", \"setenv\", key, no_proxy], check=True)\n\n\ndef unset_launchd_proxy() -> None:\n    if sys.platform != \"darwin\":\n        return\n    for key in (*PROXY_ENV_KEYS, *NO_PROXY_ENV_KEYS):\n        subprocess.run([\"launchctl\", \"unsetenv\", key], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n\n\ndef write_proxy_launch_agent(proxy_url: str, no_proxy: str) -> Path:\n    path = proxy_launch_agent_path()\n    commands = []\n    for key in PROXY_ENV_KEYS:\n        commands.append(f\"launchctl setenv {shlex.quote(key)} {shlex.quote(proxy_url)}\")\n    for key in NO_PROXY_ENV_KEYS:\n        commands.append(f\"launchctl setenv {shlex.quote(key)} {shlex.quote(no_proxy)}\")\n    command = \"; \".join(commands)\n    content = f'''<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\">\n<dict>\n  <key>Label</key>\n  <string>{PROXY_LAUNCH_AGENT_LABEL}</string>\n  <key>ProgramArguments</key>\n  <array>\n    <string>/bin/sh</string>\n    <string>-c</string>\n    <string>{xml_escape(command)}</string>\n  </array>\n  <key>RunAtLoad</key>\n  <true/>\n</dict>\n</plist>\n'''\n    atomic_write(path, content, 0o644)\n    if sys.platform == \"darwin\":\n        subprocess.run([\"launchctl\", \"bootout\", launchctl_gui_target(), str(path)], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n        enable_launch_agent(PROXY_LAUNCH_AGENT_LABEL)\n        subprocess.run([\"launchctl\", \"bootstrap\", launchctl_gui_target(), str(path)], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n    return path\n\n\ndef remove_proxy_launch_agent() -> None:\n    path = proxy_launch_agent_path()\n    if sys.platform == \"darwin\":\n        subprocess.run([\"launchctl\", \"bootout\", launchctl_gui_target(), str(path)], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n    try:\n        path.unlink()\n    except FileNotFoundError:\n        pass\n\n\ndef probe_http_proxy(proxy_url: str, timeout: float = 12.0) -> tuple[bool, str]:\n    handler = urllib.request.ProxyHandler({\"http\": proxy_url, \"https\": proxy_url})\n    opener = urllib.request.build_opener(handler)\n    request = urllib.request.Request(\n        \"https://www.gstatic.com/generate_204\",\n        headers={\"User-Agent\": UPSTREAM_USER_AGENT},\n        method=\"HEAD\",\n    )\n    try:\n        with opener.open(request, timeout=timeout) as response:\n            code = int(response.status)\n        if 200 <= code < 400:\n            return True, f\"HTTP {code}\"\n        return False, f\"HTTP {code}\"\n    except urllib.error.HTTPError as exc:\n        if 200 <= int(exc.code) < 500:\n            return True, f\"HTTP {exc.code}\"\n        return False, f\"HTTP {exc.code}\"\n    except Exception as exc:\n        return False, str(exc)\n\n\ndef activate_proxy_runtime(home: Path, proxy_url: str, no_proxy: str) -> None:\n    \"\"\"Apply the proxy to launchd, the login LaunchAgent and config.toml.\"\"\"\n    config_path = home / \"config.toml\"\n    set_launchd_proxy(proxy_url, no_proxy)\n    write_proxy_launch_agent(proxy_url, no_proxy)\n    backup_file(config_path, home / \"backups\")\n    atomic_write(config_path, rewrite_config_for_proxy(read_config(config_path), proxy_url, no_proxy), 0o600)\n\n\ndef deactivate_proxy_runtime(home: Path) -> None:\n    \"\"\"Remove the proxy from launchd, the LaunchAgent and config.toml. Only the\n    runtime is cleared; the caller decides what to do with the saved\n    preference (proxy_preference / proxy_url) so it can be reapplied later.\"\"\"\n    config_path = home / \"config.toml\"\n    unset_launchd_proxy()\n    remove_proxy_launch_agent()\n    if shell_proxy_config_values(read_config(config_path)):\n        backup_file(config_path, home / \"backups\")\n        atomic_write(config_path, rewrite_config_without_proxy(read_config(config_path)), 0o600)\n\n\ndef proxy_runtime_present(home: Path) -> bool:\n    return bool(shell_proxy_config_values(read_config(home / \"config.toml\"))) or launchctl_getenv(\"HTTP_PROXY\") is not None\n\n\ndef apply_proxy_for_provider(home: Path, provider: str, state: dict[str, object]) -> None:\n    \"\"\"Keep the HTTP proxy scoped to official mode.\n\n    The custom API path is Codex -> local adapter (127.0.0.1) -> China-direct\n    relay; none of it should traverse a proxy, and Codex's HTTP client ignores\n    NO_PROXY, so a global proxy silently breaks the local adapter's streaming.\n    Switching to custom therefore deactivates the proxy runtime while keeping\n    the user's saved preference; switching to official reactivates it when the\n    user has one enabled. proxy_enabled tracks the *actual* runtime state (the\n    desktop reads it for its status badge); proxy_preference is the intent that\n    survives custom switches.\"\"\"\n    wants_proxy = effective_setting(state, \"proxy_preference\", \"false\") == \"true\"\n    proxy_url = effective_setting(state, \"proxy_url\", \"\")\n    no_proxy = effective_setting(state, \"proxy_no_proxy\", DEFAULT_NO_PROXY)\n    if provider == \"openai\":\n        if wants_proxy and proxy_url:\n            activate_proxy_runtime(home, proxy_url, no_proxy)\n            state[\"proxy_enabled\"] = \"true\"\n            save_state(home, state)\n            print(f\"Re-enabled the HTTP proxy for official mode: {proxy_url}\")\n        return\n    # Custom (or any non-official) provider: the proxy must not be active.\n    if proxy_runtime_present(home) or effective_setting(state, \"proxy_enabled\", \"false\") == \"true\":\n        deactivate_proxy_runtime(home)\n        state[\"proxy_enabled\"] = \"false\"\n        save_state(home, state)\n        print(\"Disabled the HTTP proxy for custom API mode (it only applies to official mode).\")\n\n\ndef rewrite_config_for_local(\n    content: str,\n    base_url: str,\n    model: str,\n    api_key: str,\n    catalog_path: Path | None,\n    reasoning_effort: str | None = None,\n) -> str:\n    sections = split_toml_sections(content)\n    rewritten: list[tuple[str, list[str]]] = []\n    for section, lines in sections:\n        if section == \"\":\n            lines = set_key(lines, \"model_provider\", CUSTOM_PROVIDER_ID)\n            lines = set_key(lines, \"model\", model)\n            # Custom always authenticates as api-key: the new Codex rejects\n            # custom models on a ChatGPT account.\n            lines = set_key(lines, \"preferred_auth_method\", \"api-key\")\n            if reasoning_effort:\n                lines = set_key(lines, \"model_reasoning_effort\", reasoning_effort)\n            if catalog_path is not None:\n                lines = set_key(lines, \"model_catalog_json\", str(catalog_path))\n            else:\n                lines = remove_key(lines, \"model_catalog_json\")\n        rewritten.append((section, lines))\n    rewritten = ensure_custom_provider(rewritten, base_url, api_key, [model])\n    return \"\".join(line for _, lines in rewritten for line in lines)\n\n\ndef rewrite_config_for_official(content: str, model: str) -> str:\n    sections = split_toml_sections(content)\n    rewritten: list[tuple[str, list[str]]] = []\n    for section, lines in sections:\n        if section == \"\":\n            lines = set_key(lines, \"model_provider\", \"openai\")\n            lines = set_key(lines, \"model\", model)\n            lines = set_key(lines, \"preferred_auth_method\", \"chatgpt\")\n            lines = remove_key(lines, \"model_catalog_json\")\n        elif section == f\"[model_providers.{CUSTOM_PROVIDER_ID}]\":\n            lines = remove_key(lines, \"experimental_bearer_token\")\n        rewritten.append((section, lines))\n    return \"\".join(line for _, lines in rewritten for line in lines)\n\n\ndef rewrite_config_for_parallel(\n    content: str,\n    base_url: str,\n    official_model: str,\n    custom_model: str,\n    api_key: str,\n    catalog_path: Path | None,\n    default_provider: str = \"openai\",\n    skip_login: bool = False,\n    reasoning_effort: str | None = None,\n) -> str:\n    sections = split_toml_sections(content)\n    rewritten: list[tuple[str, list[str]]] = []\n    if default_provider == CUSTOM_PROVIDER_ID:\n        selected_provider = CUSTOM_PROVIDER_ID\n        selected_model = custom_model\n    else:\n        selected_provider = \"openai\"\n        selected_model = official_model\n    # The custom provider must authenticate as api-key: the new Codex rejects\n    # custom models on a ChatGPT account, so a custom default always uses\n    # api-key regardless of the skip-login toggle.\n    auth_method = \"api-key\" if (skip_login or default_provider == CUSTOM_PROVIDER_ID) else \"chatgpt\"\n    for section, lines in sections:\n        if section == \"\":\n            lines = set_key(lines, \"model_provider\", selected_provider)\n            lines = set_key(lines, \"model\", selected_model)\n            lines = set_key(lines, \"preferred_auth_method\", auth_method)\n            # The effort setting belongs to the custom route; an official\n            # default keeps whatever effort the user chose for it.\n            if reasoning_effort and default_provider == CUSTOM_PROVIDER_ID:\n                lines = set_key(lines, \"model_reasoning_effort\", reasoning_effort)\n            if catalog_path is not None:\n                lines = set_key(lines, \"model_catalog_json\", str(catalog_path))\n            else:\n                lines = remove_key(lines, \"model_catalog_json\")\n        rewritten.append((section, lines))\n    rewritten = ensure_custom_provider(rewritten, base_url, api_key, [custom_model])\n    # CLI parity: `codex --profile ccswitch` -> custom route,\n    # `codex --profile official` -> official route.\n    ccswitch_profile = {\"model_provider\": CUSTOM_PROVIDER_ID, \"model\": custom_model}\n    if reasoning_effort:\n        ccswitch_profile[\"model_reasoning_effort\"] = reasoning_effort\n    rewritten = ensure_profile(rewritten, \"ccswitch\", ccswitch_profile)\n    rewritten = ensure_profile(\n        rewritten, \"official\", {\"model_provider\": \"openai\", \"model\": official_model}\n    )\n    return \"\".join(line for _, lines in rewritten for line in lines)\n\n\ndef read_config(config_path: Path) -> str:\n    if not config_path.exists():\n        return \"\"\n    return config_path.read_text(encoding=\"utf-8\")\n\n\ndef configured_provider(content: str) -> str:\n    for section, lines in split_toml_sections(content):\n        if section != \"\":\n            continue\n        for line in lines:\n            match = re.match(r'^\\s*model_provider\\s*=\\s*\"([^\"]+)\"', line)\n            if match:\n                return match.group(1)\n    return \"openai\"\n\n\ndef configured_model(content: str) -> str:\n    for section, lines in split_toml_sections(content):\n        if section != \"\":\n            continue\n        for line in lines:\n            match = re.match(r'^\\s*model\\s*=\\s*\"([^\"]+)\"', line)\n            if match:\n                return match.group(1)\n    return DEFAULT_OFFICIAL_MODEL\n\n\ndef model_catalog_path(home: Path) -> Path:\n    return home / MODEL_CATALOG_NAME\n\n\ndef custom_model_entry(\n    model: str,\n    display_name: str,\n    template: dict[str, object] | None = None,\n) -> dict[str, object]:\n    # Prefer cloning a real official model so the entry carries every field\n    # Codex requires (shell_type, model_messages, base_instructions, etc.).\n    if template is not None:\n        entry = copy.deepcopy(template)\n        entry[\"slug\"] = model\n        entry[\"display_name\"] = display_name\n        entry[\"description\"] = \"Custom model registered by Codex Switch\"\n        entry[\"priority\"] = 100\n        entry.pop(\"upgrade\", None)\n        entry.pop(\"availability_nux\", None)\n        return entry\n    return {\n        \"slug\": model,\n        \"display_name\": display_name,\n        \"description\": \"Custom model registered by Codex Switch\",\n        \"shell_type\": \"shell_command\",\n        \"visibility\": \"list\",\n        \"supported_in_api\": True,\n        \"priority\": 1,\n        \"additional_speed_tiers\": [],\n        \"service_tiers\": [],\n        \"availability_nux\": None,\n        \"upgrade\": None,\n        \"supports_reasoning_summaries\": True,\n        \"default_reasoning_summary\": \"none\",\n        \"support_verbosity\": True,\n        \"default_verbosity\": \"medium\",\n        \"apply_patch_tool_type\": \"freeform\",\n        \"web_search_tool_type\": \"text_and_image\",\n        \"truncation_policy\": {\"mode\": \"tokens\", \"limit\": 10000},\n        \"supports_parallel_tool_calls\": True,\n        \"supports_image_detail_original\": True,\n        \"context_window\": 200000,\n        \"max_context_window\": 200000,\n        \"max_output_tokens\": 100000,\n        \"effective_context_window_percent\": 95,\n        \"experimental_supported_tools\": [],\n        \"supported_reasoning_levels\": [\n            {\"effort\": \"low\", \"description\": \"Fast responses with lighter reasoning\"},\n            {\"effort\": \"medium\", \"description\": \"Balances speed and reasoning depth for everyday tasks\"},\n            {\"effort\": \"high\", \"description\": \"Greater reasoning depth for complex problems\"},\n        ],\n        \"default_reasoning_level\": \"medium\",\n        \"input_modalities\": [\"text\", \"image\"],\n        \"output_modalities\": [\"text\"],\n        \"supports_search_tool\": True,\n        \"use_responses_lite\": False,\n    }\n\n\ndef load_official_models(home: Path) -> list[dict[str, object]]:\n    source = home / \"models_cache.json\"\n    if not source.exists():\n        return []\n    try:\n        data = json.loads(source.read_text(encoding=\"utf-8\"))\n    except json.JSONDecodeError:\n        return []\n    models = data.get(\"models\")\n    if not isinstance(models, list):\n        return []\n    return [dict(item) for item in models if isinstance(item, dict)]\n\n\ndef official_model_slugs(home: Path) -> set[str]:\n    return {item[\"slug\"] for item in load_official_models(home) if isinstance(item.get(\"slug\"), str)}\n\n\ndef official_model_options(home: Path) -> list[str]:\n    models = [\n        item for item in load_official_models(home)\n        if isinstance(item.get(\"slug\"), str) and item[\"slug\"].strip()\n        and not item[\"slug\"].startswith(CUSTOM_MODEL_SLUG_PREFIX)\n        and item.get(\"visibility\", \"list\") == \"list\"\n    ]\n    models.sort(key=lambda item: (\n        item[\"priority\"] if isinstance(item.get(\"priority\"), (int, float)) else float(\"inf\")\n    ))\n    return list(dict.fromkeys(item[\"slug\"] for item in models))\n\n\ndef resolve_official_model(home: Path, requested: str | None = None, warn: bool = False) -> str:\n    options = official_model_options(home)\n    candidate = (requested or \"\").strip()\n    if candidate and (\n        candidate in options or (not options and not candidate.startswith(CUSTOM_MODEL_SLUG_PREFIX))\n    ):\n        return candidate\n    selected = options[0] if options else DEFAULT_OFFICIAL_MODEL\n    if warn and candidate and candidate != selected:\n        print(f\"official_model_warn: 官方模型 {candidate} 不在当前 Codex 模型目录中，已改用 {selected}。\")\n    return selected\n\n\ndef ensure_distinct_custom_model(home: Path, custom_model: str, official_model: str | None = None) -> None:\n    reserved = official_model_slugs(home)\n    if official_model:\n        reserved.add(official_model)\n    if custom_model in reserved:\n        raise SwitchError(\n            \"Codex custom model ID must be different from official model IDs. \"\n            f\"`{custom_model}` is already reserved. Use an internal ID such as \"\n            f\"`{CUSTOM_MODEL_SLUG_PREFIX}{custom_model}` and map it to the real upstream model.\"\n        )\n\n\ndef custom_slug_for_upstream(home: Path, upstream_model: str, official_model: str | None = None) -> str:\n    \"\"\"Return a Codex-visible custom slug that cannot collide with official models.\"\"\"\n    candidate = upstream_model.strip()\n    if not candidate:\n        raise SwitchError(\"custom model cannot be empty\")\n    reserved = official_model_slugs(home)\n    if official_model:\n        reserved.add(official_model)\n    if candidate.startswith(CUSTOM_MODEL_SLUG_PREFIX) and candidate not in reserved:\n        return candidate\n    if candidate in reserved:\n        return f\"{CUSTOM_MODEL_SLUG_PREFIX}{candidate}\"\n    return candidate\n\n\ndef upstream_model_for_state(state: dict[str, object], fallback: str) -> str:\n    return effective_setting(state, \"local_upstream_model\", effective_setting(state, \"adapter_upstream_model\", fallback))\n\n\ndef reasoning_effort_for_state(state: dict[str, object]) -> str:\n    effort = effective_setting(state, \"local_reasoning_effort\", DEFAULT_REASONING_EFFORT)\n    return effort if effort in REASONING_EFFORTS else DEFAULT_REASONING_EFFORT\n\n\ndef historical_model_slugs(home: Path) -> list[str]:\n    \"\"\"Every model id referenced by existing threads, in stable order.\n\n    Codex's model_catalog_json REPLACES the built-in catalog, so any model a\n    saved conversation used must also be present here or the desktop app cannot\n    resolve (and therefore cannot list/restore) that conversation. We collect\n    the model ids from the local thread databases so the generated catalog stays\n    a superset of what history needs.\n    \"\"\"\n    slugs: list[str] = []\n    seen: set[str] = set()\n    databases = list((home / \"sqlite\").glob(\"state_*.sqlite\")) + list(home.glob(\"state_*.sqlite\"))\n    for database in databases:\n        try:\n            connection = sqlite3.connect(database)\n        except sqlite3.Error:\n            continue\n        try:\n            if \"model\" not in sqlite_columns(connection, \"threads\"):\n                continue\n            for (value,) in connection.execute(\n                \"SELECT DISTINCT model FROM threads WHERE model IS NOT NULL AND model <> ''\"\n            ):\n                if isinstance(value, str) and value not in seen:\n                    seen.add(value)\n                    slugs.append(value)\n        except sqlite3.Error:\n            continue\n        finally:\n            connection.close()\n    return slugs\n\n\ndef custom_model_catalog(\n    home: Path,\n    model: str,\n    display_name: str,\n    additional_models: list[tuple[str, str]] | None = None,\n    visible_provider: str = CUSTOM_PROVIDER_ID,\n) -> dict[str, object]:\n    # The catalog must be a SUPERSET of everything Codex history needs because\n    # model_catalog_json replaces the built-in catalog. So we keep all official\n    # models verbatim (original names), add any model referenced by existing\n    # conversations (so they still resolve and restore), and finally add the\n    # custom model with its user-defined display name.\n    official = load_official_models(home)\n    by_slug = {item.get(\"slug\"): item for item in official if isinstance(item.get(\"slug\"), str)}\n    if model and model in by_slug:\n        raise SwitchError(\n            f\"Custom model ID `{model}` collides with an official Codex model. \"\n            f\"Use `{CUSTOM_MODEL_SLUG_PREFIX}{model}` for the Codex-visible ID.\"\n        )\n\n    # Clone a real official model so synthesized entries carry every required field.\n    template: dict[str, object] | None = None\n    for slug, _ in additional_models or []:\n        if slug in by_slug:\n            template = by_slug[slug]\n            break\n    if template is None and official:\n        template = official[0]\n\n    models = list(official)\n    seen = set(by_slug)\n\n    # When the active provider is not openai, hide official models from the\n    # picker so users only see models routable through the active provider.\n    if visible_provider != \"openai\":\n        for m in models:\n            m[\"visibility\"] = \"hide\"\n\n    # Preserve historical models referenced by saved conversations, but hide\n    # them from the picker so it isn't cluttered with old/experimental slugs.\n    # They stay in the catalog only so those conversations still resolve.\n    for slug in historical_model_slugs(home):\n        if slug and slug not in seen and slug != model:\n            entry = custom_model_entry(slug, slug, template)\n            entry[\"visibility\"] = \"hide\"\n            models.append(entry)\n            seen.add(slug)\n\n    extras = list(additional_models or [])\n    for slug, name in extras:\n        if slug and slug not in seen:\n            entry = custom_model_entry(slug, name or slug, template)\n            entry[\"visibility\"] = \"list\" if visible_provider == CUSTOM_PROVIDER_ID else \"hide\"\n            models.append(entry)\n            seen.add(slug)\n\n    if model:\n        vis = \"list\" if visible_provider == CUSTOM_PROVIDER_ID else \"hide\"\n        entry = custom_model_entry(model, display_name, template)\n        entry[\"visibility\"] = vis\n        models.append(entry)\n        seen.add(model)\n\n    return {\"models\": models}\n\n\ndef write_model_catalog(\n    path: Path,\n    model: str,\n    display_name: str | None = None,\n    additional_models: list[tuple[str, str]] | None = None,\n    visible_provider: str = CUSTOM_PROVIDER_ID,\n) -> None:\n    catalog = custom_model_catalog(path.parent, model, display_name or model, additional_models, visible_provider)\n    atomic_write(\n        path,\n        json.dumps(catalog, indent=2, ensure_ascii=False) + \"\\n\",\n        0o600,\n    )\n\n\ndef rollout_files(home: Path) -> list[Path]:\n    roots = [home / \"sessions\", home / \"archived_sessions\"]\n    files: list[Path] = []\n    for root in roots:\n        if root.exists():\n            files.extend(root.rglob(\"rollout-*.jsonl\"))\n    return sorted(files)\n\n\ndef repair_legacy_message_ids(home: Path) -> tuple[int, int, Path | None]:\n    \"\"\"Repair message IDs emitted by Codex Switch versions before 0.7.13.\n\n    The chat-stream bridge accidentally used ``item_`` for assistant messages.\n    Codex persists those IDs in rollout files and later includes them when a\n    conversation is resumed. Native Responses endpoints require message IDs to\n    start with ``msg_``, so switching that conversation to an official/native\n    provider fails before the model can answer.\n\n    Only the invalid ID prefix is changed; message content and conversation\n    metadata are left untouched. Every changed rollout is backed up first.\n    \"\"\"\n    state = load_state(home)\n    if state.get(MESSAGE_ID_REPAIR_STATE_KEY) == MESSAGE_ID_REPAIR_VERSION:\n        return 0, 0, None\n\n    changed_files = 0\n    changed_ids = 0\n    backup_root: Path | None = None\n    scan_complete = True\n    for path in rollout_files(home):\n        try:\n            if path.stat().st_size == 0:\n                continue\n            with path.open(\"rb\") as handle, mmap.mmap(handle.fileno(), 0, access=mmap.ACCESS_READ) as mapped:\n                if (\n                    mapped.find(b'\"item_') < 0\n                    or mapped.find(b'\"response_item\"') < 0\n                    or mapped.find(b'\"message\"') < 0\n                ):\n                    continue\n            text = path.read_text(encoding=\"utf-8\")\n        except (OSError, UnicodeError, ValueError):\n            scan_complete = False\n            continue\n        # Most installations have hundreds of large rollouts but only a small\n        # number written by the affected adapter. The memory-mapped prefilter\n        # avoids decoding unaffected files, and the one-time migration marker\n        # skips all rollout I/O on subsequent switches.\n        output: list[str] = []\n        file_changes = 0\n        for segment in text.splitlines(keepends=True):\n            line = segment[:-1] if segment.endswith(\"\\n\") else segment\n            ending = \"\\n\" if segment.endswith(\"\\n\") else \"\"\n            if line.endswith(\"\\r\"):\n                line = line[:-1]\n                ending = \"\\r\\n\"\n            next_line = line\n            try:\n                record = json.loads(line)\n            except json.JSONDecodeError:\n                output.append(segment)\n                continue\n            payload = record.get(\"payload\")\n            if (\n                record.get(\"type\") == \"response_item\"\n                and isinstance(payload, dict)\n                and payload.get(\"type\") == \"message\"\n                and isinstance(payload.get(\"id\"), str)\n                and payload[\"id\"].startswith(\"item_\")\n            ):\n                payload[\"id\"] = \"msg_\" + payload[\"id\"][len(\"item_\"):]\n                next_line = json.dumps(record, ensure_ascii=False, separators=(\",\", \":\"))\n                file_changes += 1\n            output.append(next_line + ending)\n        if not file_changes:\n            continue\n        if backup_root is None:\n            backup_root = home / \"backups_state\" / \"message-id-repair\" / datetime.now().strftime(\"%Y%m%d-%H%M%S\")\n            suffix = 1\n            while backup_root.exists():\n                backup_root = backup_root.with_name(f\"{backup_root.name}-{suffix}\")\n                suffix += 1\n        relative = path.relative_to(home)\n        backup_path = backup_root / relative\n        backup_path.parent.mkdir(parents=True, exist_ok=True)\n        shutil.copy2(path, backup_path)\n        original_stat = path.stat()\n        atomic_write(path, \"\".join(output), stat.S_IMODE(original_stat.st_mode) or 0o600)\n        os.utime(path, (original_stat.st_atime, original_stat.st_mtime))\n        changed_files += 1\n        changed_ids += file_changes\n    if scan_complete:\n        state = load_state(home)\n        state[MESSAGE_ID_REPAIR_STATE_KEY] = MESSAGE_ID_REPAIR_VERSION\n        save_state(home, state)\n    return changed_files, changed_ids, backup_root\n\n\ndef repair_legacy_message_ids_and_report(home: Path) -> None:\n    repaired_files, repaired_ids, repair_backup = repair_legacy_message_ids(home)\n    if repaired_ids:\n        print(f\"Repaired {repaired_ids} legacy message ID(s) in {repaired_files} conversation file(s).\")\n        print(f\"message_id_backup: {repair_backup}\")\n\n\ndef sqlite_columns(connection: sqlite3.Connection, table: str) -> set[str]:\n    return {row[1] for row in connection.execute(f\"PRAGMA table_info({table})\")}\n\n\ndef print_migration(home: Path, provider: str, model: str, args: argparse.Namespace) -> None:\n    # Deliberately a no-op. Re-stamping every saved conversation's provider/model\n    # destroyed conversation metadata and was based on a false premise (the\n    # desktop app does not filter the conversation list by provider). Switching\n    # must never rewrite existing conversations' provider/model metadata. Kept\n    # for CLI compatibility\n    # (`--migrate-latest` is accepted but no longer mutates saved conversations).\n    return\n\n\ndef strip_trailing_slash(value: str) -> str:\n    return value.rstrip(\"/\")\n\n\ndef chat_completions_url(base_url: str) -> str:\n    base = strip_trailing_slash(base_url)\n    if base.endswith(\"/v1\"):\n        return f\"{base}/chat/completions\"\n    return f\"{base}/v1/chat/completions\"\n\n\ndef responses_url(base_url: str) -> str:\n    base = strip_trailing_slash(base_url)\n    if base.endswith(\"/v1\"):\n        return f\"{base}/responses\"\n    return f\"{base}/v1/responses\"\n\n\ndef models_url(base_url: str) -> str:\n    base = strip_trailing_slash(base_url)\n    if base.endswith(\"/v1\"):\n        return f\"{base}/models\"\n    return f\"{base}/v1/models\"\n\n\ndef fetch_upstream_models(base_url: str, api_key: str, timeout: float = 20.0) -> list[str]:\n    \"\"\"GET the upstream's OpenAI-style /v1/models and return the model IDs.\n\n    Raises SwitchError with a user-facing message on any failure (missing\n    endpoint, auth, bad JSON) so the desktop can show it verbatim. The\n    UPSTREAM_USER_AGENT header is required: some relays sit behind a CDN that\n    rejects the default urllib UA with 403/1010.\n    \"\"\"\n    if not base_url.strip():\n        raise SwitchError(\"请先填写自定义 API 地址。\")\n    headers = {\"User-Agent\": UPSTREAM_USER_AGENT}\n    if api_key.strip():\n        headers[\"Authorization\"] = f\"Bearer {api_key.strip()}\"\n    request = urllib.request.Request(models_url(base_url), headers=headers, method=\"GET\")\n    try:\n        with urllib.request.urlopen(request, timeout=timeout) as response:\n            payload = json.loads(response.read().decode(\"utf-8\"))\n    except urllib.error.HTTPError as exc:\n        detail = \"\"\n        try:\n            detail = exc.read(300).decode(\"utf-8\", errors=\"replace\")\n        except Exception:\n            pass\n        raise SwitchError(f\"获取模型列表失败：HTTP {exc.code} {detail}\".strip()) from exc\n    except Exception as exc:  # URLError, timeout, JSON errors, …\n        raise SwitchError(f\"获取模型列表失败：{exc}\") from exc\n    # OpenAI shape: {\"data\": [{\"id\": \"...\"}]}. Some relays return a bare list.\n    items = payload.get(\"data\") if isinstance(payload, dict) else payload\n    if not isinstance(items, list):\n        raise SwitchError(\"该接入点未返回标准的模型列表（缺少 data 数组）。\")\n    seen: set[str] = set()\n    models: list[str] = []\n    for item in items:\n        model_id = item.get(\"id\") if isinstance(item, dict) else (item if isinstance(item, str) else None)\n        if isinstance(model_id, str) and model_id.strip() and model_id not in seen:\n            seen.add(model_id)\n            models.append(model_id.strip())\n    if not models:\n        raise SwitchError(\"该接入点返回了空的模型列表。\")\n    return models\n\n\n# Fields from Codex's Responses requests that third-party / relay Responses\n# implementations most often reject with 400: OpenAI-bookkeeping fields first,\n# generation-tuning fields as a last resort. Tools are never dropped — losing\n# function calls would silently break Codex.\n_RESPONSES_PASSTHROUGH_DROP_TIERS: tuple[tuple[str, ...], ...] = (\n    (\"store\", \"include\", \"prompt_cache_key\", \"safety_identifier\", \"service_tier\", \"stream_options\", \"user\", \"metadata\"),\n    (\"reasoning\", \"text\", \"truncation\"),\n)\n\n# Statuses that suggest the upstream rejected a request field, so a sanitized\n# retry may succeed. Anything else (401/403/404/429/5xx) won't be fixed by\n# removing fields.\n_SANITIZE_RETRY_CODES = {400, 415, 422}\n\n# Routes (base_url, model) whose /v1/responses endpoint decisively rejected\n# even the most sanitized payload. Remembered for the adapter's lifetime so\n# every subsequent request goes straight to the chat bridge instead of paying\n# 3 rejected round-trips first — which also multiplies rate-limit pressure on\n# the relay during Codex's automatic reconnects. The adapter is restarted on\n# every config save, so this never pins a stale verdict across saves.\n_RESPONSES_UNSUPPORTED_ROUTES: set[tuple[str, str]] = set()\n\n\ndef normalize_responses_message_ids(payload: dict[str, object]) -> dict[str, object]:\n    \"\"\"Return a request copy with legacy ``item_`` message IDs made valid.\n\n    This is the in-flight safety net for conversations already loaded by Codex;\n    the on-disk repair handles subsequent official-provider resumes.\n    \"\"\"\n    normalized = dict(payload)\n    raw_input = payload.get(\"input\")\n    if not isinstance(raw_input, list):\n        return normalized\n    normalized_input: list[object] = []\n    for raw_item in raw_input:\n        if not isinstance(raw_item, dict):\n            normalized_input.append(raw_item)\n            continue\n        item = dict(raw_item)\n        item_id = item.get(\"id\")\n        if item.get(\"type\") == \"message\" and isinstance(item_id, str) and item_id.startswith(\"item_\"):\n            item[\"id\"] = \"msg_\" + item_id[len(\"item_\"):]\n        normalized_input.append(item)\n    normalized[\"input\"] = normalized_input\n    return normalized\n\n\ndef normalize_response_output_message_ids(payload: dict[str, object]) -> dict[str, object]:\n    \"\"\"Normalize message IDs returned by Responses-compatible relays.\"\"\"\n    normalized = dict(payload)\n    raw_output = payload.get(\"output\")\n    if not isinstance(raw_output, list):\n        return normalized\n    output: list[object] = []\n    for raw_item in raw_output:\n        if not isinstance(raw_item, dict):\n            output.append(raw_item)\n            continue\n        item = dict(raw_item)\n        item_id = item.get(\"id\")\n        if item.get(\"type\") == \"message\" and isinstance(item_id, str) and item_id.startswith(\"item_\"):\n            item[\"id\"] = \"msg_\" + item_id[len(\"item_\"):]\n        output.append(item)\n    normalized[\"output\"] = output\n    return normalized\n\n\ndef responses_passthrough_payloads(request: dict[str, object], upstream_model: str, stream: bool) -> list[dict[str, object]]:\n    \"\"\"Payload attempts for native /v1/responses passthrough, most complete first.\"\"\"\n    base = normalize_responses_message_ids(request)\n    base[\"model\"] = upstream_model\n    base[\"stream\"] = stream\n    attempts = [base]\n    dropped: set[str] = set()\n    for tier in _RESPONSES_PASSTHROUGH_DROP_TIERS:\n        dropped.update(tier)\n        candidate = {key: value for key, value in base.items() if key not in dropped}\n        if len(candidate) != len(attempts[-1]):\n            attempts.append(candidate)\n    return attempts\n\n\ndef _append_error(errors: list[str] | None, message: str) -> None:\n    if errors is not None:\n        errors.append(message[:300])\n\n\ndef upstream_failure_message(errors: list[str]) -> str:\n    \"\"\"The error Codex shows when no upstream route produced a response.\n\n    A relay's content-moderation block is explained first, in Chinese: Codex\n    truncates long errors, and the raw rejection reads like a transient\n    failure that retrying would fix, when every retry of the same\n    conversation is rejected again.\n    \"\"\"\n    message = \"upstream did not return a usable response\"\n    if errors:\n        message += \": \" + \" ; \".join(errors)\n    joined = \" \".join(errors)\n    if \"content_policy_violation\" in joined:\n        reference = re.search(r\"\\brly_[0-9A-Za-z]+\", joined)\n        contact = f\"把编号 {reference.group(0)} 发给中转站客服\" if reference else \"把下面的报错发给中转站客服\"\n        message = f\"中转站内容审核拦截了这个会话：请新开会话，或{contact}。 {message}\"\n    return message\n\n\ndef _is_reasoning_item(value: object) -> bool:\n    return isinstance(value, dict) and value.get(\"type\") == \"reasoning\"\n\n\ndef _drop_reasoning_from_output(container: object) -> None:\n    \"\"\"In place: remove every reasoning entry from a container's ``output``\n    list (top-level for a complete response object, or nested under\n    ``response`` for created/completed events).\"\"\"\n    if isinstance(container, dict) and isinstance(container.get(\"output\"), list):\n        container[\"output\"] = [\n            entry for entry in container[\"output\"] if not _is_reasoning_item(entry)\n        ]\n\n\ndef sanitize_reasoning_in_payload(obj: object) -> bool:\n    \"\"\"Drop reasoning items so a custom-provider conversation never persists a\n    reasoning shell that the official Responses API later 404s on.\n\n    A relay reasoning item carries a temporary id and no real\n    ``encrypted_content``. Codex stores it verbatim, and after switching back\n    to the official provider (``store=false``) the API does a store lookup on\n    that id and fails (\"Item with id 'rs_tmp_…' not found\"). Emptying the\n    content (the old behavior) wasn't enough — the id itself is the problem —\n    so the reasoning item must not reach Codex at all.\n\n    Returns ``True`` when ``obj`` is itself a standalone reasoning SSE event\n    whose entire ``event:``/``data:`` frame the caller should drop (a per-item\n    ``output_item.*`` event whose ``item`` is reasoning, or a reasoning-scoped\n    ``response.reasoning*`` delta/summary event). Otherwise reasoning entries\n    are stripped from any ``output`` array in place and ``False`` is returned.\n    \"\"\"\n    if not isinstance(obj, dict):\n        return False\n    if _is_reasoning_item(obj.get(\"item\")):\n        return True\n    event_type = obj.get(\"type\")\n    if isinstance(event_type, str) and event_type.startswith(\"response.reasoning\"):\n        return True\n    _drop_reasoning_from_output(obj)\n    _drop_reasoning_from_output(obj.get(\"response\"))\n    return False\n\n\ndef _http_error_detail(exc: urllib.error.HTTPError) -> str:\n    try:\n        return exc.read(500).decode(\"utf-8\", errors=\"replace\")\n    except Exception:\n        return \"\"\n\n\n# Above roughly this size, a send-phase connection drop is almost certainly the\n# relay's request-body cap (nginx defaults to client_max_body_size 1m; ICE\n# measured: 0.96MB accepted, 1.75MB dropped) — deterministic, so retrying only\n# wastes ~60s per attempt. Below it, treat the drop as transient and retry.\n_BODY_CAP_HINT_BYTES = 900 * 1024\n\n\ndef _is_connection_drop(exc: Exception) -> bool:\n    \"\"\"True for send/connect-phase drops: broken pipe, connection reset, or\n    the server closing without a response — also when wrapped in URLError.\"\"\"\n    probe: object = exc\n    if isinstance(exc, urllib.error.URLError) and not isinstance(exc, urllib.error.HTTPError):\n        probe = exc.reason\n    if isinstance(probe, (BrokenPipeError, ConnectionResetError, ConnectionAbortedError)):\n        return True\n    text = str(probe)\n    return \"Broken pipe\" in text or \"Remote end closed connection\" in text or \"Connection reset\" in text\n\n\n# HTTP statuses that mean the endpoint/model/key is clearly wrong (worth\n# blocking the save). 429 / 5xx / connection errors are transient and must not.\n_PROBE_CONFIG_ERROR_CODES = {400, 401, 403, 404, 405, 422}\n\n\ndef _probe_endpoint(url: str, payload: dict[str, object], api_key: str, timeout: float) -> tuple[int, str]:\n    \"\"\"POST a tiny request. Returns (status_code, detail). status_code is the\n    HTTP code, or 0 when the endpoint could not be reached / any other error.\n    Never raises — a probe must never crash the save.\"\"\"\n    try:\n        request = urllib.request.Request(\n            url,\n            data=json.dumps(payload).encode(\"utf-8\"),\n            headers={\"Content-Type\": \"application/json\", \"Authorization\": f\"Bearer {api_key}\", \"User-Agent\": UPSTREAM_USER_AGENT},\n            method=\"POST\",\n        )\n        with urllib.request.urlopen(request, timeout=timeout) as response:\n            response.read(4096)\n        return 200, \"ok\"\n    except urllib.error.HTTPError as exc:\n        body = \"\"\n        try:\n            body = exc.read(400).decode(\"utf-8\", errors=\"replace\")\n        except Exception:\n            pass\n        return int(exc.code), f\"HTTP {exc.code} {body}\".strip()\n    except Exception as exc:  # URLError, OSError, http.client.*, ValueError, …\n        return 0, str(exc)\n\n\ndef probe_custom_upstream(base_url: str, model: str, api_key: str, timeout: float = 20.0) -> tuple[str, str, str]:\n    \"\"\"Probe the custom API at save time. Try the Codex-native Responses API\n    first, then Chat Completions. Returns (status, protocol, detail) where\n    status is \"ok\" (reachable), \"rejected\" (endpoint/model/key clearly wrong on\n    both protocols), or \"unverified\" (transient / couldn't reach — don't block).\"\"\"\n    code1, detail1 = _probe_endpoint(\n        responses_url(base_url),\n        {\"model\": model, \"input\": \"hi\", \"max_output_tokens\": 16, \"stream\": False},\n        api_key,\n        timeout,\n    )\n    if code1 == 200:\n        return \"ok\", \"responses\", \"ok\"\n    code2, detail2 = _probe_endpoint(\n        chat_completions_url(base_url),\n        {\"model\": model, \"messages\": [{\"role\": \"user\", \"content\": \"hi\"}], \"max_tokens\": 16, \"stream\": False},\n        api_key,\n        timeout,\n    )\n    if code2 == 200:\n        return \"ok\", \"chat\", \"ok\"\n    detail = f\"/responses → {detail1}\\n/chat/completions → {detail2}\"\n    if code1 in _PROBE_CONFIG_ERROR_CODES and code2 in _PROBE_CONFIG_ERROR_CODES:\n        return \"rejected\", \"\", detail\n    return \"unverified\", \"\", detail\n\n\ndef response_content_to_text(content: object) -> str:\n    if isinstance(content, str):\n        return content\n    if isinstance(content, list):\n        chunks: list[str] = []\n        for item in content:\n            if not isinstance(item, dict):\n                continue\n            text = item.get(\"text\")\n            if isinstance(text, str) and item.get(\"type\") in {\"input_text\", \"output_text\", \"text\"}:\n                chunks.append(text)\n        return \"\\n\".join(chunks)\n    return \"\"\n\n\ndef responses_input_to_chat_messages(request: dict[str, object]) -> list[dict[str, object]]:\n    messages: list[dict[str, object]] = []\n    instructions = request.get(\"instructions\")\n    if isinstance(instructions, str) and instructions.strip():\n        messages.append({\"role\": \"system\", \"content\": instructions})\n    raw_input = request.get(\"input\")\n    if isinstance(raw_input, str):\n        messages.append({\"role\": \"user\", \"content\": raw_input})\n    elif isinstance(raw_input, list):\n        for item in raw_input:\n            if not isinstance(item, dict):\n                continue\n            item_type = item.get(\"type\")\n            role = item.get(\"role\")\n            if item_type == \"message\" or role in {\"system\", \"developer\", \"user\", \"assistant\"}:\n                chat_role = \"system\" if role == \"developer\" else role if isinstance(role, str) else \"user\"\n                msg: dict[str, object] = {\"role\": chat_role, \"content\": response_content_to_text(item.get(\"content\"))}\n                if chat_role == \"assistant\":\n                    reasoning = item.get(\"reasoning_content\")\n                    if not reasoning:\n                        content = item.get(\"content\")\n                        if isinstance(content, list):\n                            for part in content:\n                                if isinstance(part, dict) and part.get(\"type\") == \"reasoning\" and isinstance(part.get(\"text\"), str):\n                                    reasoning = part[\"text\"]\n                                    break\n                    if reasoning:\n                        msg[\"reasoning_content\"] = reasoning\n                messages.append(msg)\n            elif item_type == \"function_call\":\n                call_id = str(item.get(\"call_id\") or item.get(\"id\") or \"\")\n                tool_call = {\n                    \"id\": call_id,\n                    \"type\": \"function\",\n                    \"function\": {\n                        \"name\": str(item.get(\"name\") or \"tool\"),\n                        \"arguments\": str(item.get(\"arguments\") or \"{}\"),\n                    },\n                }\n                if messages and messages[-1].get(\"role\") == \"assistant\" and isinstance(messages[-1].get(\"tool_calls\"), list):\n                    messages[-1][\"tool_calls\"].append(tool_call)\n                else:\n                    messages.append({\n                        \"role\": \"assistant\",\n                        \"content\": None,\n                        \"tool_calls\": [tool_call],\n                    })\n            elif item_type == \"function_call_output\":\n                messages.append({\n                    \"role\": \"tool\",\n                    \"tool_call_id\": str(item.get(\"call_id\") or \"\"),\n                    \"content\": response_content_to_text(item.get(\"output\")) or str(item.get(\"output\") or \"\"),\n                })\n    if not messages:\n        messages.append({\"role\": \"user\", \"content\": \"\"})\n    return messages\n\n\ndef responses_tools_to_chat_tools(tools: object) -> list[dict[str, object]]:\n    if not isinstance(tools, list):\n        return []\n    output: list[dict[str, object]] = []\n    for tool in tools:\n        if not isinstance(tool, dict):\n            continue\n        if tool.get(\"type\") == \"function\" and isinstance(tool.get(\"name\"), str):\n            output.append({\n                \"type\": \"function\",\n                \"function\": {\n                    \"name\": tool[\"name\"],\n                    \"description\": tool.get(\"description\") or \"\",\n                    \"parameters\": tool.get(\"parameters\") or {},\n                },\n            })\n    return output\n\n\ndef responses_request_to_chat_payload(request: dict[str, object], upstream_model: str, stream: bool) -> dict[str, object]:\n    payload: dict[str, object] = {\n        \"model\": upstream_model,\n        \"messages\": responses_input_to_chat_messages(request),\n        \"stream\": stream,\n    }\n    tools = responses_tools_to_chat_tools(request.get(\"tools\"))\n    if tools:\n        payload[\"tools\"] = tools\n    for key in (\"temperature\", \"top_p\", \"max_tokens\", \"max_completion_tokens\"):\n        if key in request:\n            payload[key] = request[key]\n    return payload\n\n\ndef chat_message_to_response_output(message: dict[str, object]) -> list[dict[str, object]]:\n    tool_calls = message.get(\"tool_calls\")\n    if isinstance(tool_calls, list) and tool_calls:\n        output: list[dict[str, object]] = []\n        for call in tool_calls:\n            if not isinstance(call, dict):\n                continue\n            function = call.get(\"function\") if isinstance(call.get(\"function\"), dict) else {}\n            output.append({\n                \"type\": \"function_call\",\n                \"id\": str(call.get(\"id\") or f\"fc_{uuid.uuid4().hex}\"),\n                \"call_id\": str(call.get(\"id\") or f\"call_{uuid.uuid4().hex}\"),\n                \"name\": str(function.get(\"name\") or \"tool\"),\n                \"arguments\": str(function.get(\"arguments\") or \"{}\"),\n                \"status\": \"completed\",\n            })\n        return output\n    text = message.get(\"content\")\n    return [{\n        \"type\": \"message\",\n        \"id\": f\"msg_{uuid.uuid4().hex}\",\n        \"status\": \"completed\",\n        \"role\": \"assistant\",\n        \"content\": [{\"type\": \"output_text\", \"text\": text if isinstance(text, str) else \"\", \"annotations\": []}],\n    }]\n\n\ndef chat_response_to_responses(chat: dict[str, object], model: str) -> dict[str, object]:\n    choices = chat.get(\"choices\")\n    message: dict[str, object] = {}\n    if isinstance(choices, list) and choices and isinstance(choices[0], dict):\n        maybe_message = choices[0].get(\"message\")\n        if isinstance(maybe_message, dict):\n            message = maybe_message\n    raw_usage = chat.get(\"usage\") or {}\n    usage = {\n        \"input_tokens\": raw_usage.get(\"input_tokens\") or raw_usage.get(\"prompt_tokens\") or 0,\n        \"output_tokens\": raw_usage.get(\"output_tokens\") or raw_usage.get(\"completion_tokens\") or 0,\n        \"total_tokens\": raw_usage.get(\"total_tokens\") or 0,\n    }\n    return {\n        \"id\": f\"resp_{uuid.uuid4().hex}\",\n        \"object\": \"response\",\n        \"created_at\": int(time.time()),\n        \"status\": \"completed\",\n        \"model\": model,\n        \"output\": chat_message_to_response_output(message),\n        \"usage\": usage,\n    }\n\n\nclass AdapterServer(http.server.ThreadingHTTPServer):\n    def __init__(self, server_address: tuple[str, int], home: Path):\n        super().__init__(server_address, AdapterHandler)\n        self.home = home\n\n\nclass AdapterHandler(http.server.BaseHTTPRequestHandler):\n    server: AdapterServer\n\n    def log_message(self, format: str, *args: object) -> None:\n        return\n\n    def send_json(self, status: int, payload: dict[str, object]) -> None:\n        data = json.dumps(payload, ensure_ascii=False).encode(\"utf-8\")\n        self.send_response(status)\n        self.send_header(\"Content-Type\", \"application/json\")\n        self.send_header(\"Content-Length\", str(len(data)))\n        self.end_headers()\n        self.wfile.write(data)\n\n    def do_GET(self) -> None:\n        if self.path in {\"/health\", \"/v1/health\"}:\n            self.send_json(200, {\"status\": \"ok\"})\n            return\n        if self.path in {\"/models\", \"/v1/models\"}:\n            self._serve_models()\n            return\n        self.send_json(404, {\"error\": {\"message\": \"not found\"}})\n\n    def _serve_models(self) -> None:\n        state = load_state(self.server.home)\n        model = effective_setting(state, \"local_model\", DEFAULT_CUSTOM_MODEL)\n        display = effective_setting(state, \"local_model_display_name\", model)\n        ts = int(time.time())\n        self.send_json(200, {\n            \"object\": \"list\",\n            \"data\": [\n                {\n                    \"id\": model,\n                    \"object\": \"model\",\n                    \"created\": ts,\n                    \"owned_by\": \"custom\",\n                    \"name\": display,\n                },\n            ],\n        })\n\n    def do_POST(self) -> None:\n        if self.path not in {\"/responses\", \"/v1/responses\"}:\n            self.send_json(404, {\"error\": {\"message\": \"not found\"}})\n            return\n        try:\n            length = int(self.headers.get(\"Content-Length\") or \"0\")\n            body = self.rfile.read(length)\n            request = json.loads(body.decode(\"utf-8\"))\n            if not isinstance(request, dict):\n                raise ValueError(\"request body must be a JSON object\")\n            self.proxy_response(request)\n        except Exception as exc:\n            self.send_json(500, {\"error\": {\"message\": str(exc)}})\n\n    def proxy_response(self, request: dict[str, object]) -> None:\n        state = load_state(self.server.home)\n        auth = load_auth(self.server.home / \"auth.json\")\n        upstream_base_url = effective_setting(state, \"adapter_upstream_base_url\", effective_setting(state, \"local_base_url\", DEFAULT_BASE_URL))\n        upstream_model = upstream_model_for_state(state, DEFAULT_UPSTREAM_MODEL)\n        api_key = effective_setting(state, \"local_api_key\", str(auth.get(\"OPENAI_API_KEY\") or \"\"))\n        if not api_key:\n            raise SwitchError(\"adapter API key is missing\")\n        # \"Chat 适配器\" toggle. Off (the default) is pure Responses passthrough:\n        # Codex 0.162+ sends its tools inside an `additional_tools` input item\n        # the chat bridge can't carry, so a bridged reply would arrive with no\n        # tools at all. Returning the upstream error lets Codex retry or show it.\n        chat_bridge = effective_setting(state, \"chat_adapter\", \"false\") == \"true\"\n        stream = bool(request.get(\"stream\"))\n        resp_id = f\"resp_{uuid.uuid4().hex}\"\n\n        if stream:\n            errors: list[str] = []\n            if self.relay_responses_stream(\n                request, upstream_base_url, upstream_model, api_key, errors,\n                remember_unsupported=chat_bridge,\n            ):\n                return\n            if chat_bridge and self.relay_chat_stream(request, upstream_base_url, upstream_model, api_key, resp_id, errors):\n                return\n            message = upstream_failure_message(errors)\n            self.send_response(200)\n            self.send_header(\"Content-Type\", \"text/event-stream\")\n            self.send_header(\"Cache-Control\", \"no-cache\")\n            self.end_headers()\n            self.write_sse(\"response.failed\", {\n                \"type\": \"response.failed\",\n                \"response\": {\n                    \"id\": resp_id, \"object\": \"response\",\n                    \"created_at\": int(time.time()), \"status\": \"failed\",\n                    \"model\": upstream_model, \"output\": [],\n                    \"error\": {\"message\": message},\n                },\n            })\n            self.wfile.write(b\"data: [DONE]\\n\\n\")\n            self.wfile.flush()\n            return\n\n        errors = []\n        passthrough = self.passthrough_responses(\n            request, upstream_base_url, upstream_model, api_key, resp_id, errors,\n            remember_unsupported=chat_bridge,\n        )\n        if passthrough is not None:\n            self.send_json(200, passthrough)\n            return\n        if not chat_bridge:\n            self.send_json(502, {\"error\": {\"message\": upstream_failure_message(errors)}})\n            return\n        payload = responses_request_to_chat_payload(request, upstream_model, False)\n        upstream_request = urllib.request.Request(\n            chat_completions_url(upstream_base_url),\n            data=json.dumps(payload, ensure_ascii=False).encode(\"utf-8\"),\n            headers={\n                \"Content-Type\": \"application/json\",\n                \"Authorization\": f\"Bearer {api_key}\",\n                \"User-Agent\": UPSTREAM_USER_AGENT,\n            },\n            method=\"POST\",\n        )\n        try:\n            with urllib.request.urlopen(upstream_request, timeout=600) as response:\n                chat = json.loads(response.read().decode(\"utf-8\"))\n        except urllib.error.HTTPError as exc:\n            error_body = exc.read().decode(\"utf-8\", errors=\"replace\")\n            if errors:\n                error_body += \" ; \" + \" ; \".join(errors)\n            self.send_json(exc.code, {\"error\": {\"message\": error_body}})\n            return\n\n        result = chat_response_to_responses(chat, upstream_model)\n        result[\"id\"] = resp_id\n        self.send_json(200, result)\n\n    def passthrough_responses(\n        self, request: dict[str, object],\n        upstream_base_url: str, upstream_model: str,\n        api_key: str, resp_id: str,\n        errors: list[str] | None = None,\n        remember_unsupported: bool = True,\n    ) -> dict[str, object] | None:\n        route = (upstream_base_url, upstream_model)\n        if remember_unsupported and route in _RESPONSES_UNSUPPORTED_ROUTES:\n            _append_error(errors, \"/responses → skipped (upstream rejected it earlier)\")\n            return None\n        for payload in responses_passthrough_payloads(request, upstream_model, False):\n            upstream_req = urllib.request.Request(\n                responses_url(upstream_base_url),\n                data=json.dumps(payload, ensure_ascii=False).encode(\"utf-8\"),\n                headers={\n                    \"Content-Type\": \"application/json\",\n                    \"Authorization\": f\"Bearer {api_key}\",\n                    \"User-Agent\": UPSTREAM_USER_AGENT,\n                },\n                method=\"POST\",\n            )\n            try:\n                with urllib.request.urlopen(upstream_req, timeout=600) as resp:\n                    result = json.loads(resp.read().decode(\"utf-8\"))\n            except urllib.error.HTTPError as exc:\n                _append_error(errors, f\"/responses → HTTP {exc.code} {_http_error_detail(exc)}\".strip())\n                if exc.code in {404, 405}:\n                    if remember_unsupported:\n                        _RESPONSES_UNSUPPORTED_ROUTES.add(route)\n                    return None\n                if exc.code in _SANITIZE_RETRY_CODES:\n                    continue\n                return None\n            except Exception as exc:\n                _append_error(errors, f\"/responses → {exc}\")\n                return None\n            if not isinstance(result, dict) or not isinstance(result.get(\"output\"), list):\n                _append_error(errors, \"/responses → JSON response has no output\")\n                return None\n            result = normalize_response_output_message_ids(result)\n            sanitize_reasoning_in_payload(result)\n            result[\"id\"] = resp_id\n            raw_usage = result.get(\"usage\") or {}\n            if isinstance(raw_usage, dict) and \"input_tokens\" not in raw_usage:\n                result[\"usage\"] = {\n                    \"input_tokens\": raw_usage.get(\"input_tokens\") or raw_usage.get(\"prompt_tokens\") or 0,\n                    \"output_tokens\": raw_usage.get(\"output_tokens\") or raw_usage.get(\"completion_tokens\") or 0,\n                    \"total_tokens\": raw_usage.get(\"total_tokens\") or 0,\n                }\n            return result\n        if remember_unsupported:\n            _RESPONSES_UNSUPPORTED_ROUTES.add(route)\n        return None\n\n    def relay_chat_stream(\n        self, request: dict[str, object],\n        upstream_base_url: str, upstream_model: str,\n        api_key: str, resp_id: str,\n        errors: list[str] | None = None,\n    ) -> bool:\n        \"\"\"Stream Chat Completions and convert deltas to Responses SSE events.\n\n        Returns True if the relay handled the response, False on connection\n        error or upstream rejection (reason appended to `errors`).\n        \"\"\"\n        payload = responses_request_to_chat_payload(request, upstream_model, True)\n        upstream_req = urllib.request.Request(\n            chat_completions_url(upstream_base_url),\n            data=json.dumps(payload, ensure_ascii=False).encode(\"utf-8\"),\n            headers={\n                \"Content-Type\": \"application/json\",\n                \"Authorization\": f\"Bearer {api_key}\",\n                \"Accept\": \"text/event-stream\",\n                \"User-Agent\": UPSTREAM_USER_AGENT,\n            },\n            method=\"POST\",\n        )\n        body_size = len(upstream_req.data or b\"\")\n        response = None\n        last_error: Exception | None = None\n        for attempt in range(3):\n            if attempt:\n                time.sleep(0.5 * attempt)\n            try:\n                response = urllib.request.urlopen(upstream_req, timeout=1800)\n                break\n            except urllib.error.HTTPError as exc:\n                # The upstream answered — retrying the same request won't help.\n                _append_error(errors, f\"/chat/completions → HTTP {exc.code} {_http_error_detail(exc)}\".strip())\n                return False\n            except Exception as exc:\n                if _is_connection_drop(exc) and body_size > _BODY_CAP_HINT_BYTES:\n                    # Deterministic body-cap rejection: don't burn retries on it,\n                    # tell the user how to get back under the limit instead.\n                    _append_error(\n                        errors,\n                        f\"/chat/completions → 连接被上游中断（请求体 {body_size / 1048576:.1f}MB）。\"\n                        \"中转站通常限制请求体约 1MB，当前会话上下文过长——请在 Codex 中执行 /compact 压缩会话，或开启新会话\",\n                    )\n                    return False\n                # Otherwise (e.g. RemoteDisconnected on a small request): relays\n                # under load close connections without answering. Nothing has\n                # been sent to Codex yet, so the request is safe to retry.\n                last_error = exc\n        if response is None:\n            _append_error(errors, f\"/chat/completions → {last_error} (3 attempts)\")\n            return False\n\n        content_type = (response.headers.get(\"Content-Type\") or \"\").lower()\n        if \"text/event-stream\" not in content_type:\n            # The upstream ignored stream=true and returned the complete chat\n            # response: convert it and synthesize the SSE stream.\n            try:\n                raw = response.read().decode(\"utf-8\", errors=\"replace\")\n            finally:\n                try:\n                    response.close()\n                except Exception:\n                    pass\n            try:\n                chat = json.loads(raw)\n            except json.JSONDecodeError as exc:\n                _append_error(errors, f\"/chat/completions → non-SSE body was not JSON: {exc}\")\n                return False\n            if not isinstance(chat, dict) or not chat.get(\"choices\"):\n                _append_error(errors, f\"/chat/completions → JSON response has no choices: {raw[:200]}\")\n                return False\n            result = chat_response_to_responses(chat, upstream_model)\n            result[\"id\"] = resp_id\n            self.send_response(200)\n            self.send_header(\"Content-Type\", \"text/event-stream\")\n            self.send_header(\"Cache-Control\", \"no-cache\")\n            self.end_headers()\n            self.write_sse(\"response.created\", {\n                \"type\": \"response.created\",\n                \"response\": {\n                    \"id\": resp_id, \"object\": \"response\",\n                    \"created_at\": int(time.time()), \"status\": \"in_progress\",\n                    \"model\": upstream_model, \"output\": [],\n                },\n            })\n            self.write_response_stream(result)\n            return True\n\n        self.send_response(200)\n        self.send_header(\"Content-Type\", \"text/event-stream\")\n        self.send_header(\"Cache-Control\", \"no-cache\")\n        self.end_headers()\n\n        item_id = f\"msg_{uuid.uuid4().hex}\"\n        self.write_sse(\"response.created\", {\n            \"type\": \"response.created\",\n            \"response\": {\n                \"id\": resp_id, \"object\": \"response\",\n                \"created_at\": int(time.time()), \"status\": \"in_progress\",\n                \"model\": upstream_model, \"output\": [],\n            },\n        })\n        self.write_sse(\"response.output_item.added\", {\n            \"type\": \"response.output_item.added\", \"output_index\": 0,\n            \"item\": {\"type\": \"message\", \"id\": item_id, \"status\": \"in_progress\",\n                      \"role\": \"assistant\", \"content\": []},\n        })\n        self.write_sse(\"response.content_part.added\", {\n            \"type\": \"response.content_part.added\", \"output_index\": 0,\n            \"content_index\": 0, \"item_id\": item_id,\n            \"part\": {\"type\": \"output_text\", \"text\": \"\", \"annotations\": []},\n        })\n\n        full_text = \"\"\n        tool_calls: dict[int, dict[str, str]] = {}\n        finish_reason = None\n        usage_data: dict[str, object] = {}\n        stream_ok = False\n        try:\n            buf = b\"\"\n            for chunk in response:\n                buf += chunk\n                while b\"\\n\" in buf:\n                    line_bytes, buf = buf.split(b\"\\n\", 1)\n                    line = line_bytes.decode(\"utf-8\", errors=\"replace\").strip()\n                    if not line.startswith(\"data:\"):\n                        continue\n                    data_str = line[5:].strip()\n                    if data_str == \"[DONE]\":\n                        stream_ok = True\n                        break\n                    try:\n                        delta_obj = json.loads(data_str)\n                    except json.JSONDecodeError:\n                        continue\n                    choices = delta_obj.get(\"choices\")\n                    if not isinstance(choices, list) or not choices:\n                        if delta_obj.get(\"usage\"):\n                            usage_data = delta_obj[\"usage\"]\n                        continue\n                    choice = choices[0]\n                    if not isinstance(choice, dict):\n                        continue\n                    fr = choice.get(\"finish_reason\")\n                    if fr:\n                        finish_reason = fr\n                    delta = choice.get(\"delta\")\n                    if not isinstance(delta, dict):\n                        continue\n                    text_chunk = delta.get(\"content\")\n                    if isinstance(text_chunk, str) and text_chunk:\n                        full_text += text_chunk\n                        self.write_sse(\"response.output_text.delta\", {\n                            \"type\": \"response.output_text.delta\",\n                            \"output_index\": 0, \"content_index\": 0,\n                            \"item_id\": item_id, \"delta\": text_chunk,\n                        })\n                    tc = delta.get(\"tool_calls\")\n                    if isinstance(tc, list):\n                        for t in tc:\n                            if not isinstance(t, dict):\n                                continue\n                            idx = t.get(\"index\", 0)\n                            if idx not in tool_calls:\n                                tool_calls[idx] = {\n                                    \"id\": str(t.get(\"id\") or f\"call_{uuid.uuid4().hex}\"),\n                                    \"name\": \"\", \"arguments\": \"\",\n                                }\n                            if isinstance(t.get(\"id\"), str):\n                                tool_calls[idx][\"id\"] = t[\"id\"]\n                            fn = t.get(\"function\")\n                            if isinstance(fn, dict):\n                                if isinstance(fn.get(\"name\"), str):\n                                    tool_calls[idx][\"name\"] += fn[\"name\"]\n                                if isinstance(fn.get(\"arguments\"), str):\n                                    tool_calls[idx][\"arguments\"] += fn[\"arguments\"]\n                    if not isinstance(delta_obj.get(\"usage\"), dict):\n                        u = delta_obj.get(\"usage\")\n                        if isinstance(u, dict):\n                            usage_data = u\n                if stream_ok:\n                    break\n            stream_ok = True\n        except Exception:\n            pass\n        finally:\n            try:\n                response.close()\n            except Exception:\n                pass\n\n        try:\n            if tool_calls:\n                self.write_sse(\"response.content_part.done\", {\n                    \"type\": \"response.content_part.done\", \"output_index\": 0,\n                    \"content_index\": 0, \"item_id\": item_id,\n                    \"part\": {\"type\": \"output_text\", \"text\": full_text, \"annotations\": []},\n                })\n                self.write_sse(\"response.output_item.done\", {\n                    \"type\": \"response.output_item.done\", \"output_index\": 0,\n                    \"item\": {\"type\": \"message\", \"id\": item_id, \"status\": \"completed\",\n                              \"role\": \"assistant\",\n                              \"content\": [{\"type\": \"output_text\", \"text\": full_text, \"annotations\": []}]},\n                })\n                for tc_idx, tc in sorted(tool_calls.items()):\n                    fc_item_id = f\"fc_{uuid.uuid4().hex}\"\n                    fc_item = {\n                        \"type\": \"function_call\", \"id\": fc_item_id,\n                        \"call_id\": tc[\"id\"], \"name\": tc[\"name\"],\n                        \"arguments\": tc[\"arguments\"], \"status\": \"completed\",\n                    }\n                    out_idx = 1 + tc_idx\n                    self.write_sse(\"response.output_item.added\", {\n                        \"type\": \"response.output_item.added\", \"output_index\": out_idx,\n                        \"item\": dict(fc_item, status=\"in_progress\"),\n                    })\n                    if tc[\"arguments\"]:\n                        self.write_sse(\"response.function_call_arguments.delta\", {\n                            \"type\": \"response.function_call_arguments.delta\",\n                            \"output_index\": out_idx, \"item_id\": fc_item_id,\n                            \"delta\": tc[\"arguments\"],\n                        })\n                    self.write_sse(\"response.function_call_arguments.done\", {\n                        \"type\": \"response.function_call_arguments.done\",\n                        \"output_index\": out_idx, \"item_id\": fc_item_id,\n                        \"arguments\": tc[\"arguments\"],\n                    })\n                    self.write_sse(\"response.output_item.done\", {\n                        \"type\": \"response.output_item.done\",\n                        \"output_index\": out_idx, \"item\": fc_item,\n                    })\n                output_items: list[dict[str, object]] = [{\n                    \"type\": \"message\", \"id\": item_id, \"status\": \"completed\",\n                    \"role\": \"assistant\",\n                    \"content\": [{\"type\": \"output_text\", \"text\": full_text, \"annotations\": []}],\n                }]\n                for tc_idx, tc in sorted(tool_calls.items()):\n                    output_items.append({\n                        \"type\": \"function_call\", \"id\": f\"fc_{uuid.uuid4().hex}\",\n                        \"call_id\": tc[\"id\"], \"name\": tc[\"name\"],\n                        \"arguments\": tc[\"arguments\"], \"status\": \"completed\",\n                    })\n            else:\n                self.write_sse(\"response.output_text.done\", {\n                    \"type\": \"response.output_text.done\", \"output_index\": 0,\n                    \"content_index\": 0, \"item_id\": item_id, \"text\": full_text,\n                })\n                self.write_sse(\"response.content_part.done\", {\n                    \"type\": \"response.content_part.done\", \"output_index\": 0,\n                    \"content_index\": 0, \"item_id\": item_id,\n                    \"part\": {\"type\": \"output_text\", \"text\": full_text, \"annotations\": []},\n                })\n                self.write_sse(\"response.output_item.done\", {\n                    \"type\": \"response.output_item.done\", \"output_index\": 0,\n                    \"item\": {\"type\": \"message\", \"id\": item_id, \"status\": \"completed\",\n                              \"role\": \"assistant\",\n                              \"content\": [{\"type\": \"output_text\", \"text\": full_text, \"annotations\": []}]},\n                })\n                output_items = [{\n                    \"type\": \"message\", \"id\": item_id, \"status\": \"completed\",\n                    \"role\": \"assistant\",\n                    \"content\": [{\"type\": \"output_text\", \"text\": full_text, \"annotations\": []}],\n                }]\n\n            usage = {\n                \"input_tokens\": usage_data.get(\"input_tokens\") or usage_data.get(\"prompt_tokens\") or 0,\n                \"output_tokens\": usage_data.get(\"output_tokens\") or usage_data.get(\"completion_tokens\") or 0,\n                \"total_tokens\": usage_data.get(\"total_tokens\") or 0,\n            }\n            completed_response = {\n                \"id\": resp_id, \"object\": \"response\",\n                \"created_at\": int(time.time()), \"status\": \"completed\",\n                \"model\": upstream_model, \"output\": output_items, \"usage\": usage,\n            }\n            self.write_sse(\"response.completed\", {\"type\": \"response.completed\", \"response\": completed_response})\n            self.wfile.write(b\"data: [DONE]\\n\\n\")\n            self.wfile.flush()\n        except Exception:\n            pass\n        return True\n\n    def relay_responses_stream(\n        self, request: dict[str, object],\n        upstream_base_url: str, upstream_model: str, api_key: str,\n        errors: list[str] | None = None,\n        remember_unsupported: bool = True,\n    ) -> bool:\n        \"\"\"Relay the upstream's native /v1/responses SSE stream straight to Codex.\n\n        Sends the full Codex request first, then progressively sanitized copies\n        when the upstream rejects it with 400/415/422 — relays that do support\n        the Responses protocol often reject OpenAI-bookkeeping fields such as\n        store/include. An upstream that ignores stream=true and answers with\n        the complete JSON object is synthesized into SSE events instead of\n        being discarded. Returns True if the response was handled; on False\n        the caller falls back to the chat-completions bridge, with the reason\n        for each failed attempt appended to `errors`.\n\n        ``remember_unsupported`` lets a rejected route go straight to the chat\n        bridge on later requests; pure passthrough turns it off because there\n        is no bridge to skip to.\n        \"\"\"\n        route = (upstream_base_url, upstream_model)\n        if remember_unsupported and route in _RESPONSES_UNSUPPORTED_ROUTES:\n            _append_error(errors, \"/responses → skipped (upstream rejected it earlier)\")\n            return False\n        for payload in responses_passthrough_payloads(request, upstream_model, True):\n            upstream_req = urllib.request.Request(\n                responses_url(upstream_base_url),\n                data=json.dumps(payload, ensure_ascii=False).encode(\"utf-8\"),\n                headers={\n                    \"Content-Type\": \"application/json\",\n                    \"Authorization\": f\"Bearer {api_key}\",\n                    \"Accept\": \"text/event-stream\",\n                    \"User-Agent\": UPSTREAM_USER_AGENT,\n                },\n                method=\"POST\",\n            )\n            try:\n                response = urllib.request.urlopen(upstream_req, timeout=1800)\n            except urllib.error.HTTPError as exc:\n                _append_error(errors, f\"/responses → HTTP {exc.code} {_http_error_detail(exc)}\".strip())\n                if exc.code in {404, 405}:\n                    if remember_unsupported:\n                        _RESPONSES_UNSUPPORTED_ROUTES.add(route)\n                    return False\n                if exc.code in _SANITIZE_RETRY_CODES:\n                    continue\n                return False\n            except Exception as exc:\n                _append_error(errors, f\"/responses → {exc}\")\n                return False\n            content_type = (response.headers.get(\"Content-Type\") or \"\").lower()\n            if \"text/event-stream\" not in content_type:\n                return self.synthesize_stream_from_responses_json(response, upstream_model, errors)\n            return self._relay_sse_body(response, upstream_model)\n        # Even the most sanitized payload was rejected: the endpoint/model\n        # combination doesn't do Responses, so stop asking.\n        if remember_unsupported:\n            _RESPONSES_UNSUPPORTED_ROUTES.add(route)\n        return False\n\n    def synthesize_stream_from_responses_json(\n        self, response: object, upstream_model: str, errors: list[str] | None = None,\n    ) -> bool:\n        \"\"\"Turn a complete (non-SSE) Responses JSON object into the SSE stream\n        Codex expects — for upstreams that ignore stream=true.\"\"\"\n        try:\n            raw = response.read().decode(\"utf-8\", errors=\"replace\")\n        finally:\n            try:\n                response.close()\n            except Exception:\n                pass\n        try:\n            result = json.loads(raw)\n        except json.JSONDecodeError as exc:\n            _append_error(errors, f\"/responses → non-SSE body was not JSON: {exc}\")\n            return False\n        if not isinstance(result, dict) or not isinstance(result.get(\"output\"), list):\n            _append_error(errors, f\"/responses → JSON response has no output: {raw[:200]}\")\n            return False\n        resp_id = str(result.get(\"id\") or f\"resp_{uuid.uuid4().hex}\")\n        result = normalize_response_output_message_ids(result)\n        sanitize_reasoning_in_payload(result)\n        result[\"id\"] = resp_id\n        raw_usage = result.get(\"usage\") or {}\n        if isinstance(raw_usage, dict) and \"input_tokens\" not in raw_usage:\n            result[\"usage\"] = {\n                \"input_tokens\": raw_usage.get(\"input_tokens\") or raw_usage.get(\"prompt_tokens\") or 0,\n                \"output_tokens\": raw_usage.get(\"output_tokens\") or raw_usage.get(\"completion_tokens\") or 0,\n                \"total_tokens\": raw_usage.get(\"total_tokens\") or 0,\n            }\n        self.send_response(200)\n        self.send_header(\"Content-Type\", \"text/event-stream\")\n        self.send_header(\"Cache-Control\", \"no-cache\")\n        self.end_headers()\n        self.write_sse(\"response.created\", {\n            \"type\": \"response.created\",\n            \"response\": {\n                \"id\": resp_id, \"object\": \"response\",\n                \"created_at\": int(time.time()), \"status\": \"in_progress\",\n                \"model\": upstream_model, \"output\": [],\n            },\n        })\n        self.write_response_stream(result)\n        return True\n\n    def _sanitize_sse_event(self, event: bytes) -> bytes | None:\n        \"\"\"Given one full SSE event (its ``event:``/``data:`` lines joined by\n        ``\\\\n``, without the trailing blank line), return the bytes to forward\n        or ``None`` to drop the whole event.\n\n        A reasoning event is dropped in its entirety — dropping only its\n        ``data:`` line would leave a dangling ``event:`` line and a malformed\n        frame. Complete-response events have reasoning pruned from their output\n        array; every other event passes through with its ``data:`` re-encoded.\n        \"\"\"\n        lines = event.split(b\"\\n\")\n        data_index = None\n        for index, raw in enumerate(lines):\n            body = raw[:-1] if raw.endswith(b\"\\r\") else raw\n            if body.startswith(b\"data:\"):\n                data_index = index\n                payload = body[5:].strip()\n                break\n        if data_index is None:\n            return event\n        if not payload or payload == b\"[DONE]\":\n            return event\n        try:\n            obj = json.loads(payload.decode(\"utf-8\"))\n        except Exception:\n            return event\n        if sanitize_reasoning_in_payload(obj):\n            return None\n        rewritten = b\"data: \" + json.dumps(obj, ensure_ascii=False).encode(\"utf-8\")\n        if lines[data_index].endswith(b\"\\r\"):\n            rewritten += b\"\\r\"\n        lines[data_index] = rewritten\n        return b\"\\n\".join(lines)\n\n    def _relay_sse_body(self, response: object, upstream_model: str) -> bool:\n        self.send_response(200)\n        self.send_header(\"Content-Type\", \"text/event-stream\")\n        self.send_header(\"Cache-Control\", \"no-cache\")\n        self.end_headers()\n        stream_ok = False\n        buf = b\"\"\n        event_lines: list[bytes] = []\n\n        def flush_event() -> None:\n            if not event_lines:\n                return\n            event = b\"\\n\".join(event_lines)\n            event_lines.clear()\n            out = self._sanitize_sse_event(event)\n            if out is not None:\n                self.wfile.write(out + b\"\\n\\n\")\n\n        try:\n            for chunk in response:\n                buf += chunk\n                # SSE events are delimited by a blank line (LF or CRLF). Buffer\n                # each event's lines and flush the whole event at the boundary,\n                # so a reasoning event is dropped as one frame.\n                while b\"\\n\" in buf:\n                    line, buf = buf.split(b\"\\n\", 1)\n                    if line == b\"\" or line == b\"\\r\":\n                        flush_event()\n                    else:\n                        event_lines.append(line)\n                self.wfile.flush()\n            if buf:\n                event_lines.append(buf)\n            flush_event()\n            self.wfile.flush()\n            stream_ok = True\n        except Exception:\n            pass\n        finally:\n            try:\n                response.close()\n            except Exception:\n                pass\n        if not stream_ok:\n            try:\n                self.write_sse(\"response.failed\", {\n                    \"type\": \"response.failed\",\n                    \"response\": {\n                        \"id\": f\"resp_{uuid.uuid4().hex}\",\n                        \"object\": \"response\",\n                        \"created_at\": int(time.time()),\n                        \"status\": \"failed\",\n                        \"model\": upstream_model,\n                        \"output\": [],\n                        \"error\": {\"message\": \"upstream stream disconnected before completion\"},\n                    },\n                })\n                self.wfile.write(b\"data: [DONE]\\n\\n\")\n                self.wfile.flush()\n            except Exception:\n                pass\n        return True\n\n    def write_sse(self, event: str, payload: dict[str, object]) -> None:\n        self.wfile.write(f\"event: {event}\\n\".encode(\"utf-8\"))\n        self.wfile.write((\"data: \" + json.dumps(payload, ensure_ascii=False) + \"\\n\\n\").encode(\"utf-8\"))\n        self.wfile.flush()\n\n    def write_response_stream(self, response_payload: dict[str, object]) -> None:\n        response_payload = normalize_response_output_message_ids(response_payload)\n        output = response_payload.get(\"output\")\n        if isinstance(output, list):\n            # Drop reasoning items entirely (custom mode) before enumerating, so\n            # no reasoning shell is emitted and the surviving items re-index into\n            # a contiguous output sequence. The pruned list is written back so\n            # the final response.completed carries the same clean output.\n            output = [item for item in output if not _is_reasoning_item(item)]\n            response_payload[\"output\"] = output\n            for index, item in enumerate(output):\n                if not isinstance(item, dict):\n                    continue\n                in_progress = dict(item)\n                in_progress[\"status\"] = \"in_progress\"\n                default_prefix = \"msg\" if item.get(\"type\") == \"message\" else \"item\"\n                item_id = str(item.get(\"id\") or f\"{default_prefix}_{uuid.uuid4().hex}\")\n                in_progress[\"id\"] = item_id\n                self.write_sse(\"response.output_item.added\", {\"type\": \"response.output_item.added\", \"output_index\": index, \"item\": in_progress})\n                if item.get(\"type\") == \"message\":\n                    content = item.get(\"content\")\n                    if isinstance(content, list):\n                        for content_index, part in enumerate(content):\n                            if not isinstance(part, dict):\n                                continue\n                            self.write_sse(\"response.content_part.added\", {\"type\": \"response.content_part.added\", \"output_index\": index, \"content_index\": content_index, \"item_id\": item_id, \"part\": part})\n                            text = part.get(\"text\")\n                            if isinstance(text, str) and text:\n                                self.write_sse(\"response.output_text.delta\", {\"type\": \"response.output_text.delta\", \"output_index\": index, \"content_index\": content_index, \"item_id\": item_id, \"delta\": text})\n                                self.write_sse(\"response.output_text.done\", {\"type\": \"response.output_text.done\", \"output_index\": index, \"content_index\": content_index, \"item_id\": item_id, \"text\": text})\n                            self.write_sse(\"response.content_part.done\", {\"type\": \"response.content_part.done\", \"output_index\": index, \"content_index\": content_index, \"item_id\": item_id, \"part\": part})\n                elif item.get(\"type\") == \"function_call\":\n                    arguments = item.get(\"arguments\")\n                    if not isinstance(arguments, str):\n                        arguments = \"{}\"\n                    if arguments:\n                        self.write_sse(\"response.function_call_arguments.delta\", {\"type\": \"response.function_call_arguments.delta\", \"output_index\": index, \"item_id\": item_id, \"delta\": arguments})\n                    self.write_sse(\"response.function_call_arguments.done\", {\"type\": \"response.function_call_arguments.done\", \"output_index\": index, \"item_id\": item_id, \"arguments\": arguments})\n                completed_item = dict(item)\n                completed_item[\"id\"] = item_id\n                self.write_sse(\"response.output_item.done\", {\"type\": \"response.output_item.done\", \"output_index\": index, \"item\": completed_item})\n        self.write_sse(\"response.completed\", {\"type\": \"response.completed\", \"response\": response_payload})\n        self.wfile.write(b\"data: [DONE]\\n\\n\")\n        self.wfile.flush()\n\n\ndef run_adapter(args: argparse.Namespace) -> int:\n    home = Path(args.codex_home).expanduser() if args.codex_home else codex_home()\n    server = AdapterServer((args.host, args.port), home)\n    print(f\"Codex Switch adapter listening on http://{args.host}:{args.port}/v1\")\n    server.serve_forever()\n    return 0\n\n\ndef adapter_launch_agent_path() -> Path:\n    return Path.home() / \"Library\" / \"LaunchAgents\" / f\"{ADAPTER_LAUNCH_AGENT_LABEL}.plist\"\n\n\ndef launchctl_gui_target() -> str:\n    return f\"gui/{os.getuid()}\"\n\n\ndef write_adapter_launch_agent(home: Path, host: str = DEFAULT_ADAPTER_HOST, port: int = DEFAULT_ADAPTER_PORT) -> Path:\n    path = adapter_launch_agent_path()\n    path.parent.mkdir(parents=True, exist_ok=True)\n    # Copy the running script to a stable location under codex_home and point the\n    # LaunchAgent there. The app bundle can be run via macOS App Translocation\n    # from a temporary, read-only path that disappears when the app quits/updates;\n    # baking that path into the LaunchAgent kills the adapter mid-stream\n    # (\"stream closed before response.completed\"). A stable copy survives all that.\n    source = Path(sys.argv[0]).resolve()\n    stable_script = home / \"codex-switch-adapter.py\"\n    try:\n        shutil.copy2(source, stable_script)\n        stable_script.chmod(0o755)\n        cli_path = str(stable_script)\n    except OSError:\n        cli_path = str(source)\n    log_path = str(home / \"codex-switch-adapter.log\")\n    content = f'''<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<plist version=\"1.0\">\n<dict>\n  <key>Label</key>\n  <string>{ADAPTER_LAUNCH_AGENT_LABEL}</string>\n  <key>ProgramArguments</key>\n  <array>\n    <string>{xml_escape(cli_path)}</string>\n    <string>adapter</string>\n    <string>serve</string>\n    <string>--host</string>\n    <string>{host}</string>\n    <string>--port</string>\n    <string>{port}</string>\n    <string>--codex-home</string>\n    <string>{xml_escape(str(home))}</string>\n  </array>\n  <key>RunAtLoad</key>\n  <true/>\n  <key>KeepAlive</key>\n  <true/>\n  <key>StandardOutPath</key>\n  <string>{xml_escape(log_path)}</string>\n  <key>StandardErrorPath</key>\n  <string>{xml_escape(log_path)}</string>\n</dict>\n</plist>\n'''\n    atomic_write(path, content, 0o644)\n    return path\n\n\ndef start_adapter_launch_agent(home: Path) -> Path:\n    path = write_adapter_launch_agent(home)\n    target = launchctl_gui_target()\n    subprocess.run([\"launchctl\", \"bootout\", target, str(path)], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n    enable_launch_agent(ADAPTER_LAUNCH_AGENT_LABEL)\n    result = subprocess.run([\"launchctl\", \"bootstrap\", target, str(path)], check=False, capture_output=True, text=True)\n    if result.returncode != 0:\n        detail = \" \".join((result.stderr or result.stdout or \"\").split()) or f\"exit status {result.returncode}\"\n        raise SwitchError(\n            f\"launchd refused to load the adapter LaunchAgent {ADAPTER_LAUNCH_AGENT_LABEL} ({detail}). \"\n            \"Open System Settings > General > Login Items & Extensions > Allow in the Background, \"\n            \"make sure Codex Switch is switched on, then save the configuration again.\"\n        )\n    subprocess.run([\"launchctl\", \"kickstart\", \"-k\", f\"{target}/{ADAPTER_LAUNCH_AGENT_LABEL}\"], check=False)\n    return path\n\n\ndef thread_database_paths(home: Path) -> list[Path]:\n    # The merged ChatGPT.app desktop (2026-07) keeps the live thread DB at\n    # ~/.codex/state_5.sqlite; older standalone Codex builds used\n    # ~/.codex/sqlite/state_5.sqlite. Update every copy that exists so\n    # whichever one the installed app reads stays in sync.\n    candidates = (home / \"state_5.sqlite\", home / \"sqlite\" / \"state_5.sqlite\")\n    return [path for path in candidates if path.exists()]\n\n\ndef backup_sqlite_database(db_path: Path, backup_dir: Path) -> Path:\n    backup_dir.mkdir(parents=True, exist_ok=True)\n    target = backup_dir / db_path.name\n    source = sqlite3.connect(str(db_path), timeout=5)\n    try:\n        destination = sqlite3.connect(str(target))\n        try:\n            source.backup(destination)\n        finally:\n            destination.close()\n    finally:\n        source.close()\n    return target\n\n\ndef sync_thread_provider_tags(home: Path, provider: str, model: str) -> int:\n    \"\"\"Retag conversations to the active provider AND model after a switch.\n\n    The merged ChatGPT.app filters the sidebar by model_provider (verified\n    2026-07: with the custom provider active every openai-tagged conversation\n    vanishes, and vice versa), so retagging the provider keeps history visible.\n    But provider and model must move together: a custom-model row left tagged\n    to the openai provider (or vice versa) is an invalid pair the new Codex\n    rejects with \"model … is not supported when using Codex with a ChatGPT\n    account\". Custom models also can't be detected by name (slugs like\n    stealth/ox-alpha carry no codex-switch/ prefix), so both columns are set\n    to the active pair — a continued conversation uses the active model anyway.\n    Only sqlite is touched (the source Codex reads for a thread's model);\n    rollout files are never rewritten (that corrupted message IDs before\n    0.7.13). Databases are backed up first, and failures never abort the switch.\n    \"\"\"\n    updated = 0\n    for db_path in thread_database_paths(home):\n        try:\n            backup_sqlite_database(\n                db_path,\n                home / \"backups_state\" / \"provider-tag\" / datetime.now().strftime(\"%Y%m%d-%H%M%S\"),\n            )\n            connection = sqlite3.connect(str(db_path), timeout=5)\n            try:\n                with connection:\n                    cursor = connection.execute(\n                        \"UPDATE threads SET model_provider = ?, model = ? \"\n                        \"WHERE model_provider != ? OR model != ?\",\n                        (provider, model, provider, model),\n                    )\n                    updated += cursor.rowcount\n            finally:\n                connection.close()\n        except sqlite3.Error as exc:\n            print(f\"provider_tag_warn: {db_path}: {exc}\")\n    return updated\n\n\ndef stop_codex_before_switch(args: argparse.Namespace) -> bool:\n    if not getattr(args, \"restart_codex\", False):\n        return False\n    subprocess.run(\n        [\"osascript\", \"-e\", 'tell application \"Codex\" to quit'],\n        check=False,\n        stdout=subprocess.DEVNULL,\n        stderr=subprocess.DEVNULL,\n    )\n    # Relaunching while the old process is still terminating makes\n    # LaunchServices fail with -609 (connectionInvalid). A fixed pause is not\n    # enough: a Codex with hundreds of threads takes several seconds to flush\n    # state on quit, so poll until the process is actually gone (up to ~15s).\n    for _ in range(30):\n        probe = subprocess.run(\n            [\"pgrep\", \"-x\", \"Codex\"],\n            check=False,\n            stdout=subprocess.DEVNULL,\n            stderr=subprocess.DEVNULL,\n        )\n        if probe.returncode != 0:\n            return True\n        time.sleep(0.5)\n    raise SwitchError(\"Codex did not quit within 15 seconds; configuration was not changed. Please close Codex and retry.\")\n\n\ndef restart_codex(\n    args: argparse.Namespace,\n    home: Path,\n    expected_provider: str,\n    expected_model: str,\n    already_stopped: bool = False,\n) -> None:\n    if not getattr(args, \"restart_codex\", False):\n        return\n    if not already_stopped:\n        stop_codex_before_switch(args)\n    # Repair after Codex has flushed and closed its rollout files. The repair is\n    # intentionally narrow and backed up; doing it here avoids racing a live\n    # desktop process during a normal app-driven switch.\n    repair_legacy_message_ids_and_report(home)\n    # The merged ChatGPT.app filters the conversation sidebar by\n    # model_provider (unlike the old standalone desktop), so retag the sqlite\n    # rows to the newly selected provider while Codex is stopped — otherwise\n    # the whole history vanishes from the list after a switch. Only the\n    # provider column changes; conversation content, per-thread models, and\n    # rollout files stay untouched (see sync_thread_provider_tags).\n    tagged = sync_thread_provider_tags(home, expected_provider, expected_model)\n    if tagged:\n        print(f\"Tagged {tagged} conversation(s) to {expected_provider}/{expected_model} so they stay listed and usable.\")\n    launched = None\n    for attempt in range(3):\n        if attempt:\n            time.sleep(2.0)\n        launched = subprocess.run([\"open\", \"-a\", \"Codex\"], check=False, capture_output=True, text=True)\n        if launched.returncode == 0:\n            break\n    if launched is None or launched.returncode != 0:\n        # The switch itself already succeeded by this point; a failed relaunch\n        # must not report the whole operation as failed.\n        print(\"restart_warn: 配置已保存成功，但自动重启 Codex 失败，请手动打开 Codex.app。\")\n        detail = ((launched.stderr or launched.stdout or \"\").strip() if launched is not None else \"\")\n        if detail:\n            print(detail)\n        return\n    time.sleep(RESTART_SETTLE_SECONDS)\n    config = read_config(home / \"config.toml\")\n    actual_provider = configured_provider(config)\n    actual_model = configured_model(config)\n    if actual_provider != expected_provider or actual_model != expected_model:\n        raise SwitchError(\n            f\"Codex restarted with provider/model {actual_provider}/{actual_model}, \"\n            f\"not {expected_provider}/{expected_model}.\"\n        )\n    print(\"Restarted Codex.app to reload the selected provider.\")\n\n\ndef restart_codex_after_proxy(args: argparse.Namespace) -> None:\n    if not getattr(args, \"restart_codex\", False):\n        return\n    stop_codex_before_switch(args)\n    launched = None\n    for attempt in range(3):\n        if attempt:\n            time.sleep(2.0)\n        launched = subprocess.run([\"open\", \"-a\", \"Codex\"], check=False, capture_output=True, text=True)\n        if launched.returncode == 0:\n            break\n    if launched is None or launched.returncode != 0:\n        print(\"restart_warn: 代理配置已保存成功，但自动重启 Codex 失败，请手动打开 Codex.app。\")\n        detail = ((launched.stderr or launched.stdout or \"\").strip() if launched is not None else \"\")\n        if detail:\n            print(detail)\n        return\n    time.sleep(RESTART_SETTLE_SECONDS)\n    print(\"Restarted Codex.app to reload proxy environment.\")\n\n\ndef resolve_proxy_url(args: argparse.Namespace, state: dict[str, object]) -> tuple[str, str]:\n    manual = getattr(args, \"url\", None)\n    if manual:\n        return normalize_proxy_url(manual), \"manual\"\n    if getattr(args, \"auto\", False):\n        detected = detect_clash_verge_proxy_url()\n        if not detected:\n            raise SwitchError(\"Could not detect a Clash Verge HTTP/mixed proxy port. Re-run with --url http://127.0.0.1:<port>.\")\n        return normalize_proxy_url(detected), \"clash-verge\"\n    saved = state.get(\"proxy_url\")\n    if isinstance(saved, str) and saved.strip():\n        return normalize_proxy_url(saved), \"saved\"\n    raise SwitchError(\"No proxy URL provided. Use `proxy set --url http://127.0.0.1:<port>` or `proxy apply --auto`.\")\n\n\ndef proxy_status(args: argparse.Namespace) -> int:\n    home = codex_home()\n    state = load_state(home)\n    config = read_config(home / \"config.toml\")\n    config_values = shell_proxy_config_values(config)\n    launch_agent = proxy_launch_agent_path()\n    print(f\"codex_home: {home}\")\n    print(f\"proxy_enabled: {effective_setting(state, 'proxy_enabled', 'false')}\")\n    print(f\"proxy_preference: {effective_setting(state, 'proxy_preference', 'false')}\")\n    print(f\"proxy_url: {effective_setting(state, 'proxy_url', '(missing)')}\")\n    print(f\"proxy_no_proxy: {effective_setting(state, 'proxy_no_proxy', DEFAULT_NO_PROXY)}\")\n    print(f\"proxy_source: {effective_setting(state, 'proxy_source', '(missing)')}\")\n    print(f\"launch_agent: {launch_agent if launch_agent.exists() else '(missing)'}\")\n    for key in (*PROXY_ENV_KEYS, *NO_PROXY_ENV_KEYS):\n        print(f\"config.{key}: {config_values.get(key, '(missing)')}\")\n    for key in (\"HTTP_PROXY\", \"HTTPS_PROXY\", \"NO_PROXY\"):\n        value = launchctl_getenv(key)\n        print(f\"launchd.{key}: {value if value else '(missing)'}\")\n    if getattr(args, \"probe\", False):\n        proxy_url, _ = resolve_proxy_url(args, state)\n        ok, detail = probe_http_proxy(proxy_url)\n        print(f\"probe: {'ok' if ok else 'failed'} ({detail})\")\n        if not ok:\n            return 1\n    return 0\n\n\ndef proxy_apply(args: argparse.Namespace) -> int:\n    home = codex_home()\n    config_path = home / \"config.toml\"\n    backup_dir = home / \"backups\"\n    state = load_state(home)\n    proxy_url, source = resolve_proxy_url(args, state)\n    no_proxy = getattr(args, \"no_proxy\", None) or effective_setting(state, \"proxy_no_proxy\", DEFAULT_NO_PROXY)\n    no_proxy = no_proxy.strip() or DEFAULT_NO_PROXY\n\n    if not getattr(args, \"skip_probe\", False):\n        ok, detail = probe_http_proxy(proxy_url)\n        if not ok:\n            raise SwitchError(f\"proxy probe failed for {proxy_url}: {detail}\")\n        print(f\"proxy_probe: ok ({detail})\")\n\n    # Always remember the preference so a later switch to official can reapply\n    # it; only activate now when official mode is actually the current route.\n    state[\"proxy_preference\"] = \"true\"\n    state[\"proxy_url\"] = proxy_url\n    state[\"proxy_no_proxy\"] = no_proxy\n    state[\"proxy_source\"] = source\n    current_provider = configured_provider(read_config(config_path))\n    if current_provider != \"openai\":\n        state[\"proxy_enabled\"] = \"false\"\n        save_state(home, state)\n        print(\"Saved the proxy preference. It applies only in official OpenAI mode;\")\n        print(\"switch to official to activate it (custom API must stay proxy-free).\")\n        print(f\"codex_home: {home}\")\n        print(f\"proxy_url: {proxy_url}\")\n        return 0\n\n    try:\n        set_launchd_proxy(proxy_url, no_proxy)\n    except subprocess.CalledProcessError as exc:\n        raise SwitchError(f\"launchctl setenv failed for proxy environment: {exc}\") from exc\n    try:\n        launch_agent = write_proxy_launch_agent(proxy_url, no_proxy)\n    except OSError as exc:\n        raise SwitchError(f\"failed to write proxy LaunchAgent: {exc}\") from exc\n    backup_file(config_path, backup_dir)\n    config = rewrite_config_for_proxy(read_config(config_path), proxy_url, no_proxy)\n    atomic_write(config_path, config, 0o600)\n    state[\"proxy_enabled\"] = \"true\"\n    save_state(home, state)\n\n    print(\"Applied Codex proxy environment.\")\n    print(f\"codex_home: {home}\")\n    print(f\"proxy_url: {proxy_url}\")\n    print(f\"no_proxy: {no_proxy}\")\n    print(f\"launch_agent: {launch_agent}\")\n    print(f\"backup_dir: {backup_dir}\")\n    restart_codex_after_proxy(args)\n    return 0\n\n\ndef proxy_set(args: argparse.Namespace) -> int:\n    return proxy_apply(args)\n\n\ndef proxy_off(args: argparse.Namespace) -> int:\n    home = codex_home()\n    backup_dir = home / \"backups\"\n    state = load_state(home)\n    deactivate_proxy_runtime(home)\n    # Explicit off means \"don't want the proxy at all\", so clear the preference\n    # too — otherwise a later switch to official would silently bring it back.\n    state[\"proxy_enabled\"] = \"false\"\n    state[\"proxy_preference\"] = \"false\"\n    save_state(home, state)\n    print(\"Disabled Codex proxy environment.\")\n    print(f\"codex_home: {home}\")\n    print(f\"backup_dir: {backup_dir}\")\n    restart_codex_after_proxy(args)\n    return 0\n\n\ndef switch_local(args: argparse.Namespace) -> int:\n    home = codex_home()\n    auth_path = home / \"auth.json\"\n    config_path = home / \"config.toml\"\n    catalog_path = model_catalog_path(home)\n    backup_dir = home / \"backups\"\n\n    auth = load_auth(auth_path)\n    state = load_state(home)\n    remember_current_auth(home, auth, state)\n    base_url = args.base_url or effective_setting(state, \"local_base_url\", DEFAULT_BASE_URL)\n    model = args.model or effective_setting(state, \"local_model\", DEFAULT_MODEL)\n    cached_key = state.get(\"local_api_key\")\n    stdin_key = \"\"\n    if getattr(args, \"api_key_stdin\", False):\n        stdin_key = sys.stdin.readline().strip()\n        if not stdin_key:\n            raise SwitchError(\"API key from stdin was empty.\")\n    api_key = stdin_key or args.api_key or str(auth.get(\"OPENAI_API_KEY\") or \"\").strip()\n    if not api_key and isinstance(cached_key, str):\n        api_key = cached_key.strip()\n    if not api_key:\n        raise SwitchError(\"No API key found. Re-run with --api-key, or login once with `codex login --with-api-key`.\")\n    state[\"local_api_key\"] = api_key\n    codex_stopped = stop_codex_before_switch(args)\n\n    backup_file(auth_path, backup_dir)\n    backup_file(config_path, backup_dir)\n    backup_file(catalog_path, backup_dir)\n    auth[\"OPENAI_API_KEY\"] = api_key\n    # Custom mode must authenticate as api-key so the new Codex accepts custom\n    # models (it rejects them on a ChatGPT account). Stash the ChatGPT login so\n    # switching back to official restores it.\n    stash_login_tokens(auth, state)\n    auth[\"auth_mode\"] = \"api-key\"\n    auth.pop(\"tokens\", None)\n    save_state(home, state)\n    write_auth(auth_path, auth)\n    # Never write a custom model_catalog_json (see configure_codex). Switching\n    # never retags conversations; the one-time legacy-ID repair is handled\n    # separately and leaves their content/metadata intact.\n    if catalog_path.exists():\n        catalog_path.unlink()\n    config = rewrite_config_for_local(\n        read_config(config_path), base_url, model, api_key, None, reasoning_effort_for_state(state)\n    )\n    atomic_write(config_path, config, 0o600)\n    apply_proxy_for_provider(home, \"custom\", state)\n    if not getattr(args, \"restart_codex\", False):\n        repair_legacy_message_ids_and_report(home)\n\n    print(\"Switched Codex to local relay API mode.\")\n    print(f\"codex_home: {home}\")\n    print(f\"base_url: {base_url}\")\n    print(f\"model: {model}\")\n    print(\"model_catalog_json: (built-in)\")\n    print(f\"api_key: {redacted_key(api_key)}\")\n    print(f\"backup_dir: {backup_dir}\")\n    print_migration(home, \"custom\", model, args)\n    restart_codex(args, home, \"custom\", model, already_stopped=codex_stopped)\n    return 0\n\n\ndef switch_official(args: argparse.Namespace) -> int:\n    home = codex_home()\n    auth_path = home / \"auth.json\"\n    config_path = home / \"config.toml\"\n    backup_dir = home / \"backups\"\n\n    auth = load_auth(auth_path)\n    state = load_state(home)\n    remember_current_auth(home, auth, state)\n    model = resolve_official_model(home, args.model or effective_setting(state, \"official_model\", \"\"), warn=True)\n    state[\"official_model\"] = model\n    state[\"default_provider\"] = \"openai\"\n    auth[\"auth_mode\"] = \"chatgpt\"\n    restored_login = restore_login_tokens(auth, state)\n    codex_stopped = stop_codex_before_switch(args)\n\n    backup_file(auth_path, backup_dir)\n    backup_file(config_path, backup_dir)\n    # auth.json first: a crash before save_state leaves the stash in place,\n    # which the next restore harmlessly drops in favor of the live tokens.\n    write_auth(auth_path, auth)\n    save_state(home, state)\n    if restored_login:\n        print(\"Restored the stashed ChatGPT login; no re-login needed.\")\n    config = rewrite_config_for_official(read_config(config_path), model)\n    atomic_write(config_path, config, 0o600)\n    apply_proxy_for_provider(home, \"openai\", state)\n    if not getattr(args, \"restart_codex\", False):\n        repair_legacy_message_ids_and_report(home)\n\n    print(\"Switched Codex to official ChatGPT login mode.\")\n    print(f\"codex_home: {home}\")\n    print(\"auth_mode: chatgpt\")\n    print(\"model_provider: openai\")\n    print(f\"model: {model}\")\n    print(f\"backup_dir: {backup_dir}\")\n    print(\"Existing ChatGPT login tokens, custom API key, and custom model catalog were preserved.\")\n    print_migration(home, \"openai\", model, args)\n    restart_codex(args, home, \"openai\", model, already_stopped=codex_stopped)\n    return 0\n\n\ndef configure_codex(args: argparse.Namespace) -> int:\n    home = codex_home()\n    auth_path = home / \"auth.json\"\n    config_path = home / \"config.toml\"\n    catalog_path = model_catalog_path(home)\n    backup_dir = home / \"backups\"\n\n    auth = load_auth(auth_path)\n    state = load_state(home)\n    remember_current_auth(home, auth, state)\n    base_url = args.base_url or effective_setting(state, \"local_base_url\", DEFAULT_BASE_URL)\n    requested_model = args.custom_model or args.model or upstream_model_for_state(state, DEFAULT_UPSTREAM_MODEL)\n    display_name = args.custom_model_name or effective_setting(state, \"local_model_display_name\", requested_model)\n    official_model = resolve_official_model(home, args.official_model or effective_setting(state, \"official_model\", \"\"), warn=True)\n    default_provider = args.default_provider or effective_setting(state, \"default_provider\", \"openai\")\n    if default_provider not in {\"openai\", CUSTOM_PROVIDER_ID}:\n        raise SwitchError(\"default_provider must be openai or custom\")\n    reasoning_effort = getattr(args, \"reasoning_effort\", None) or reasoning_effort_for_state(state)\n    custom_model = args.custom_model_slug or custom_slug_for_upstream(home, requested_model, official_model)\n    ensure_distinct_custom_model(home, custom_model, official_model)\n    if not display_name:\n        display_name = requested_model\n    cached_key = state.get(\"local_api_key\")\n    stdin_key = \"\"\n    if getattr(args, \"api_key_stdin\", False):\n        stdin_key = sys.stdin.readline().strip()\n        if not stdin_key:\n            raise SwitchError(\"API key from stdin was empty.\")\n    api_key = stdin_key or args.api_key or str(auth.get(\"OPENAI_API_KEY\") or \"\").strip()\n    if not api_key and isinstance(cached_key, str):\n        api_key = cached_key.strip()\n    if not api_key:\n        raise SwitchError(\"No API key found. Re-run with --api-key, or login once with `codex login --with-api-key`.\")\n\n    # Smart routing: at save time, probe the custom upstream so the user gets\n    # immediate feedback instead of a broken Codex session. Only a clear\n    # rejection (endpoint/model/key wrong on both protocols) blocks the save;\n    # transient errors (rate limit, 5xx, can't connect) just warn and proceed,\n    # and the probe never crashes the save.\n    if getattr(args, \"probe\", False) and default_provider == CUSTOM_PROVIDER_ID:\n        status, protocol, detail = probe_custom_upstream(base_url, requested_model, api_key)\n        if status == \"rejected\":\n            raise SwitchError(\n                \"自定义 API 验证失败，请检查接入点、模型 ID 和 API Key。\\n\"\n                f\"{detail}\"\n            )\n        if status == \"unverified\":\n            print(\"probe_warn: 暂时无法验证自定义 API（可能限流或临时不可用），已继续保存。\")\n            print(detail)\n        else:\n            print(f\"probe_ok: {protocol}\")\n\n    codex_stopped = stop_codex_before_switch(args)\n    backup_file(auth_path, backup_dir)\n    backup_file(config_path, backup_dir)\n    backup_file(catalog_path, backup_dir)\n    state[\"local_api_key\"] = api_key\n    state[\"local_base_url\"] = base_url\n    state[\"local_model\"] = custom_model\n    state[\"local_upstream_model\"] = requested_model\n    state[\"local_model_display_name\"] = display_name\n    state[\"official_model\"] = official_model\n    state[\"default_provider\"] = default_provider\n    if getattr(args, \"chat_adapter\", False):\n        state[\"chat_adapter\"] = \"true\"\n    else:\n        state[\"chat_adapter\"] = \"false\"\n    state[\"adapter_upstream_base_url\"] = base_url\n    state[\"adapter_upstream_model\"] = requested_model\n    provider_base_url = DEFAULT_ADAPTER_BASE_URL\n    skip_login = getattr(args, \"skip_login\", False)\n    state[\"skip_login\"] = \"true\" if skip_login else \"false\"\n    state[\"local_reasoning_effort\"] = reasoning_effort\n    # A custom default must authenticate as api-key regardless of the toggle:\n    # the new Codex rejects custom models on a ChatGPT account. Official default\n    # keeps the ChatGPT login unless the user explicitly bypasses it.\n    use_api_key_auth = skip_login or default_provider == CUSTOM_PROVIDER_ID\n\n    auth[\"OPENAI_API_KEY\"] = api_key\n    # Write ordering matters: whichever file still holds the login must be\n    # written second, so a crash between the two writes never loses it (the\n    # next restore prefers live auth.json tokens and drops the stash).\n    if use_api_key_auth:\n        stash_login_tokens(auth, state)\n        auth[\"auth_mode\"] = \"api-key\"\n        auth.pop(\"tokens\", None)\n        save_state(home, state)\n        write_auth(auth_path, auth)\n    else:\n        auth[\"auth_mode\"] = \"chatgpt\"\n        restored_login = restore_login_tokens(auth, state)\n        write_auth(auth_path, auth)\n        save_state(home, state)\n        if restored_login:\n            print(\"Restored the stashed ChatGPT login; no re-login needed.\")\n    # cc-switch lesson: never write a custom model_catalog_json. It REPLACES\n    # Codex's built-in catalog (shrinking the official model list and breaking\n    # model resolution), and a single malformed catalog makes Codex fail to load\n    # config -> the conversation list disappears. Switching must not retag saved\n    # conversations; only the one-time legacy message-ID repair may edit rollouts.\n    if catalog_path.exists():\n        catalog_path.unlink()\n    adapter_plist = start_adapter_launch_agent(home)\n    config = rewrite_config_for_parallel(\n        read_config(config_path),\n        provider_base_url,\n        official_model,\n        custom_model,\n        api_key,\n        None,\n        default_provider,\n        skip_login,\n        reasoning_effort,\n    )\n    atomic_write(config_path, config, 0o600)\n    apply_proxy_for_provider(home, default_provider, state)\n    if not getattr(args, \"restart_codex\", False):\n        repair_legacy_message_ids_and_report(home)\n\n    print(\"Configured Codex official and custom providers in parallel.\")\n    print(f\"codex_home: {home}\")\n    print(f\"model_provider: {default_provider}\")\n    print(f\"official_model: {official_model}\")\n    print(f\"custom.base_url: {provider_base_url}\")\n    print(f\"adapter_upstream_base_url: {base_url}\")\n    print(f\"adapter_launch_agent: {adapter_plist}\")\n    print(f\"custom_model: {custom_model}\")\n    print(f\"upstream_model: {requested_model}\")\n    print(f\"custom_model_name: {display_name}\")\n    print(f\"reasoning_effort: {reasoning_effort}\")\n    print(\"model_catalog_json: (built-in)\")\n    print(f\"api_key: {redacted_key(api_key)}\")\n    print(f\"backup_dir: {backup_dir}\")\n    selected_model = official_model if default_provider == \"openai\" else custom_model\n    restart_codex(args, home, default_provider, selected_model, already_stopped=codex_stopped)\n    return 0\n\n\ndef status(_: argparse.Namespace) -> int:\n    home = codex_home()\n    auth_path = home / \"auth.json\"\n    config_path = home / \"config.toml\"\n    auth = load_auth(auth_path)\n    config = read_config(config_path)\n\n    print(f\"codex_home: {home}\")\n    print(f\"auth_mode: {auth.get('auth_mode') or '(missing)'}\")\n    print(f\"api_key: {redacted_key(auth.get('OPENAI_API_KEY') if isinstance(auth.get('OPENAI_API_KEY'), str) else None)}\")\n    for key in (\"model_provider\", \"model\", \"preferred_auth_method\", \"model_catalog_json\"):\n        match = re.search(rf\"^{re.escape(key)}\\s*=\\s*\\\"([^\\\"]*)\\\"\", config, re.MULTILINE)\n        print(f\"{key}: {match.group(1) if match else '(missing)'}\")\n    base_url = re.search(\n        r\"^\\[model_providers\\.custom\\][\\s\\S]*?^base_url\\s*=\\s*\\\"([^\\\"]*)\\\"\",\n        config,\n        re.MULTILINE,\n    )\n    print(f\"custom.base_url: {base_url.group(1) if base_url else '(missing)'}\")\n    return 0\n\n\ndef upstream_models(args: argparse.Namespace) -> int:\n    \"\"\"List the models a custom/relay API advertises via /v1/models, so the\n    desktop can offer a pick-list instead of a hand-typed model ID.\"\"\"\n    home = codex_home()\n    state = load_state(home)\n    base_url = args.base_url or effective_setting(\n        state, \"adapter_upstream_base_url\", effective_setting(state, \"local_base_url\", DEFAULT_BASE_URL)\n    )\n    api_key = args.api_key or \"\"\n    if getattr(args, \"api_key_stdin\", False):\n        api_key = sys.stdin.readline().strip()\n    if not api_key:\n        auth = load_auth(home / \"auth.json\")\n        api_key = effective_setting(state, \"local_api_key\", str(auth.get(\"OPENAI_API_KEY\") or \"\"))\n    models = fetch_upstream_models(base_url, api_key)\n    for model_id in models:\n        print(model_id)\n    return 0\n\n\ndef config_show(_: argparse.Namespace) -> int:\n    home = codex_home()\n    state = load_state(home)\n    print(f\"codex_home: {home}\")\n    print(f\"local_base_url: {effective_setting(state, 'local_base_url', DEFAULT_BASE_URL)}\")\n    print(f\"local_model: {effective_setting(state, 'local_model', DEFAULT_CUSTOM_MODEL)}\")\n    print(f\"local_upstream_model: {upstream_model_for_state(state, DEFAULT_UPSTREAM_MODEL)}\")\n    print(f\"local_model_display_name: {effective_setting(state, 'local_model_display_name', effective_setting(state, 'local_model', DEFAULT_CUSTOM_MODEL))}\")\n    print(f\"official_model: {resolve_official_model(home, effective_setting(state, 'official_model', ''))}\")\n    print(f\"official_model_options: {json.dumps(official_model_options(home), ensure_ascii=False)}\")\n    print(f\"default_provider: {effective_setting(state, 'default_provider', 'openai')}\")\n    print(f\"chat_adapter: {effective_setting(state, 'chat_adapter', 'false')}\")\n    print(f\"local_reasoning_effort: {reasoning_effort_for_state(state)}\")\n    print(f\"skip_login: {effective_setting(state, 'skip_login', 'false')}\")\n    print(f\"adapter_upstream_base_url: {effective_setting(state, 'adapter_upstream_base_url', effective_setting(state, 'local_base_url', DEFAULT_BASE_URL))}\")\n    return 0\n\n\ndef config_set(args: argparse.Namespace) -> int:\n    home = codex_home()\n    state = load_state(home)\n    updates = {\n        \"local_base_url\": args.local_base_url,\n        \"local_model\": args.local_model,\n        \"local_upstream_model\": args.local_upstream_model,\n        \"local_model_display_name\": args.local_model_display_name,\n        \"official_model\": args.official_model,\n        \"default_provider\": args.default_provider,\n    }\n    for key, value in updates.items():\n        if value is not None:\n            stripped = value.strip()\n            if not stripped:\n                raise SwitchError(f\"{key} cannot be empty\")\n            state[key] = stripped\n    save_state(home, state)\n    print(\"Saved Codex Switch settings.\")\n    return config_show(args)\n\n\ndef codex_register_model(args: argparse.Namespace) -> int:\n    home = codex_home()\n    state = load_state(home)\n    model = args.model.strip()\n    if not model:\n        raise SwitchError(\"model cannot be empty\")\n    ensure_distinct_custom_model(home, model)\n    display_name = args.name.strip() if args.name else model\n    if not display_name:\n        raise SwitchError(\"model display name cannot be empty\")\n    state[\"local_model\"] = model\n    state[\"local_model_display_name\"] = display_name\n    save_state(home, state)\n    print(\"Saved custom Codex model setting.\")\n    print(f\"codex_home: {home}\")\n    print(f\"model: {model}\")\n    print(f\"custom_model_name: {display_name}\")\n    print(\"Switch to custom API mode to apply it in config.toml.\")\n    return 0\n\n\ndef load_claude_settings(settings_path: Path) -> dict[str, object]:\n    return load_json_object(settings_path)\n\n\ndef save_claude_settings(settings_path: Path, settings: dict[str, object]) -> None:\n    mode = 0o600\n    if settings_path.exists():\n        mode = stat.S_IMODE(settings_path.stat().st_mode) or 0o600\n    atomic_write(settings_path, json.dumps(settings, indent=2, ensure_ascii=False) + \"\\n\", mode)\n\n\ndef claude_env(settings: dict[str, object]) -> dict[str, object]:\n    env = settings.get(\"env\")\n    if isinstance(env, dict):\n        return env\n    env = {}\n    settings[\"env\"] = env\n    return env\n\n\ndef remember_current_claude(settings: dict[str, object], state: dict[str, object]) -> None:\n    env = claude_env(settings)\n    token = env.get(\"ANTHROPIC_AUTH_TOKEN\") or env.get(\"ANTHROPIC_API_KEY\")\n    if isinstance(token, str) and token.strip():\n        state[\"local_api_key\"] = token.strip()\n    base_url = env.get(\"ANTHROPIC_BASE_URL\")\n    if isinstance(base_url, str) and base_url.strip():\n        state[\"local_base_url\"] = base_url.strip()\n    model = env.get(\"ANTHROPIC_MODEL\")\n    if isinstance(model, str) and model.strip():\n        if env.get(\"ANTHROPIC_BASE_URL\"):\n            state[\"local_model\"] = model.strip()\n        else:\n            state[\"official_model\"] = model.strip()\n\n\ndef claude_model_from_env(env: dict[str, object], fallback: str) -> str:\n    for key in (\"ANTHROPIC_MODEL\", \"ANTHROPIC_DEFAULT_SONNET_MODEL\", \"ANTHROPIC_DEFAULT_OPUS_MODEL\"):\n        value = env.get(key)\n        if isinstance(value, str) and value.strip():\n            return value.strip()\n    return fallback\n\n\ndef switch_claude_local(args: argparse.Namespace) -> int:\n    home = claude_home()\n    settings_path = home / \"settings.json\"\n    backup_dir = home / \"backups\"\n    settings = load_claude_settings(settings_path)\n    state = load_claude_state(home)\n    env = claude_env(settings)\n    remember_current_claude(settings, state)\n\n    base_url = args.base_url or effective_setting(state, \"local_base_url\", CLAUDE_DEFAULT_BASE_URL)\n    model = args.model or effective_setting(state, \"local_model\", CLAUDE_DEFAULT_MODEL)\n    cached_key = state.get(\"local_api_key\")\n    stdin_key = \"\"\n    if getattr(args, \"auth_token_stdin\", False):\n        stdin_key = sys.stdin.readline().strip()\n        if not stdin_key:\n            raise SwitchError(\"Claude API token from stdin was empty.\")\n    api_key = stdin_key or args.auth_token or str(env.get(\"ANTHROPIC_AUTH_TOKEN\") or env.get(\"ANTHROPIC_API_KEY\") or \"\").strip()\n    if not api_key and isinstance(cached_key, str):\n        api_key = cached_key.strip()\n    if not api_key:\n        raise SwitchError(\"No Claude API token found. Re-run with --auth-token or --auth-token-stdin.\")\n\n    backup_file(settings_path, backup_dir)\n    state[\"local_base_url\"] = base_url\n    state[\"local_model\"] = model\n    state[\"local_api_key\"] = api_key\n    save_claude_state(home, state)\n\n    ch = codex_home()\n    codex_st = load_state(ch)\n    codex_st[\"adapter_upstream_base_url\"] = base_url\n    codex_st[\"adapter_upstream_model\"] = model\n    codex_st[\"local_api_key\"] = api_key\n    save_state(ch, codex_st)\n    adapter_plist = start_adapter_launch_agent(ch)\n\n    adapter_url = f\"http://{DEFAULT_ADAPTER_HOST}:{DEFAULT_ADAPTER_PORT}\"\n    env[\"ANTHROPIC_BASE_URL\"] = adapter_url\n    env[\"ANTHROPIC_AUTH_TOKEN\"] = api_key\n    env[\"ANTHROPIC_MODEL\"] = model\n    env.pop(\"ANTHROPIC_API_KEY\", None)\n    save_claude_settings(settings_path, settings)\n\n    print(\"Switched Claude Code to custom API mode.\")\n    print(f\"claude_home: {home}\")\n    print(f\"upstream_url: {base_url} (via adapter)\")\n    print(f\"adapter: {adapter_url}\")\n    print(f\"adapter_launch_agent: {adapter_plist}\")\n    print(f\"model: {model}\")\n    print(f\"api_key: {redacted_key(api_key)}\")\n    print(f\"backup_dir: {backup_dir}\")\n    print(\"Restart Claude Code terminal sessions for the new settings to take effect.\")\n    return 0\n\n\ndef switch_claude_official(args: argparse.Namespace) -> int:\n    home = claude_home()\n    settings_path = home / \"settings.json\"\n    backup_dir = home / \"backups\"\n    settings = load_claude_settings(settings_path)\n    state = load_claude_state(home)\n    env = claude_env(settings)\n    remember_current_claude(settings, state)\n\n    model = args.model or effective_setting(state, \"offici